window.TXB=window.TXB||{};TXB["svd/2Ch"]={"1:1":"وتشدد سليمان بن داود على مملكته وكان الرب إلهه معه وعظمه جدا.","1:2":"وكلم سليمان جميع إسرائيل رؤساء الألوف والمئات والقضاة وكل رئيس في كل إسرائيل رؤوس الآباء","1:3":"فذهب سليمان وكل الجماعة معه إلى المرتفعة التي في جبعون لأنه هناك كانت خيمة الاجتماع خيمة الله التي عملها موسى عبد الرب في البرية.","1:4":"وأما تابوت الله فأصعده داود من قرية يعاريم عندما هيأ له داود لأنه نصب له خيمة في أورشليم.","1:5":"ومذبح النحاس الذي عمله بصلئيل بن أوري بن حور وضعه أمام مسكن الرب. وطلب إليه سليمان والجماعة.","1:6":"وصعد سليمان هناك إلى مذبح النحاس أمام الرب الذي كان في خيمة الاجتماع وأصعد عليه ألف محرقة.","1:7":"في تلك الليلة تراءى الله لسليمان وقال له: [اسأل ماذا أعطيك].","1:8":"فقال سليمان لله: [إنك قد فعلت مع داود أبي رحمة عظيمة وملكتني مكانه.","1:9":"فالآن أيها الرب الإله ليثبت كلامك مع داود أبي لأنك قد ملكتني على شعب كثير كتراب الأرض.","1:10":"فأعطني الآن حكمة ومعرفة لأخرج أمام هذا الشعب وأدخل لأنه من يقدر أن يحكم على شعبك هذا العظيم]","1:11":"فقال الله لسليمان: [من أجل أن هذا كان في قلبك ولم تسأل غنى ولا أموالا ولا كرامة ولا أنفس مبغضيك ولا سألت أياما كثيرة بل إنما سألت لنفسك حكمة ومعرفة تحكم بهما على شعبي الذي ملكتك عليه","1:12":"قد أعطيتك حكمة ومعرفة وأعطيك غنى وأموالا وكرامة لم يكن مثلها للملوك الذين قبلك ولا يكون مثلها لمن بعدك].","1:13":"فجاء سليمان من المرتفعة التي في جبعون إلى أورشليم من أمام خيمة الاجتماع وملك على إسرائيل.","1:14":"وجمع سليمان مركبات وفرسانا فكان له ألف وأربع مئة مركبة واثنا عشر ألف فارس فجعلها في مدن المركبات ومع الملك في أورشليم.","1:15":"وجعل الملك الفضة والذهب في أورشليم مثل الحجارة وجعل الأرز كالجميز الذي في السهل في الكثرة.","1:16":"وكان مخرج الخيل التي لسليمان من مصر. وجماعة تجار الملك أخذوا جليبة بثمن","1:17":"فأصعدوا وأخرجوا من مصر المركبة بست مئة شاقل من الفضة والفرس بمئة وخمسين وهكذا لجميع ملوك الحثيين وملوك أرام كانوا يخرجون عن يدهم.","2:1":"وأمر سليمان ببناء بيت لاسم الرب وبيت لملكه.","2:2":"وأحصى سليمان سبعين ألف رجل حمال وثمانين ألف رجل نحات في الجبل ووكلاء عليهم ثلاثة آلاف وست مئة.","2:3":"وأرسل سليمان إلى حورام ملك صور قائلا: [كما فعلت مع داود أبي إذ أرسلت له أرزا ليبني له بيتا يسكن فيه","2:4":"فهئنذا أبني بيتا لاسم الرب إلهي لأقدسه له لأوقد أمامه بخورا عطرا ولخبز الوجوه الدائم وللمحرقات صباحا ومساء وللسبوت والأهلة ومواسم الرب إلهنا. هذا على إسرائيل إلى الأبد.","2:5":"والبيت الذي أنا بانيه عظيم لأن إلهنا أعظم من جميع الآلهة.","2:6":"ومن يستطيع أن يبني له بيتا لأن السماوات وسماء السماوات لا تسعه ومن أنا حتى أبني له بيتا إلا للإيقاد أمامه!","2:7":"فالآن أرسل لي رجلا حكيما في صناعة الذهب والفضة والنحاس والحديد والأرجوان والقرمز والأسمانجوني ماهرا في النقش مع الحكماء الذين عندي في يهوذا وفي أورشليم الذين أعدهم داود أبي.","2:8":"وأرسل لي خشب أرز وسرو وصندل من لبنان لأني أعلم أن عبيدك ماهرون في قطع خشب لبنان. وهوذا عبيدي مع عبيدك.","2:9":"وليعدوا لي خشبا بكثرة لأن البيت الذي أبنيه عظيم وعجيب.","2:10":"وهئنذا أعطي للقطاعين القاطعين الخشب عشرين ألف كر من الحنطة طعاما لعبيدك وعشرين ألف كر شعير وعشرين ألف بث خمر وعشرين ألف بث زيت].","2:11":"فأجاب حورام ملك صور برسالة إلى سليمان: [لأن الرب قد أحب شعبه جعلك عليهم ملكا].","2:12":"وقال حورام: [مبارك الرب إله إسرائيل الذي صنع السماء والأرض الذي أعطى داود الملك ابنا حكيما صاحب معرفة وفهم الذي يبني بيتا للرب وبيتا لملكه.","2:13":"والآن أرسلت رجلا حكيما صاحب فهم اسمه حورام أبي","2:14":"(ابن امرأة من بنات دان وأبوه رجل صوري) ماهر في صناعة الذهب والفضة والنحاس والحديد والحجارة والخشب والأرجوان والأسمانجوني والكتان والقرمز ونقش كل نوع من النقش واختراع كل اختراع يلقى عليه مع حكمائك وحكماء سيدي داود أبيك.","2:15":"والآن الحنطة والشعير والزيت والخمر التي ذكرها سيدي فليرسلها لعبيده.","2:16":"ونحن نقطع خشبا من لبنان حسب كل احتياجك ونأتي به إليك أرماثا على البحر إلى يافا. وأنت تصعده إلى أورشليم].","2:17":"وعد سليمان جميع الرجال الأجنبيين الذين في أرض إسرائيل بعد العد الذي عدهم إياه داود أبوه فوجدوا مئة وثلاثة وخمسين ألفا وست مئة.","2:18":"فجعل منهم سبعين ألف حمال وثمانين ألف قطاع على الجبل وثلاثة آلاف وست مئة وكلاء لتشغيل الشعب.","3:1":"وشرع سليمان في بناء بيت الرب في أورشليم في جبل المريا حيث تراءى لداود أبيه حيث هيأ داود مكانا في بيدر أرنان اليبوسي.","3:2":"وشرع في البناء في ثاني الشهر الثاني في السنة الرابعة لملكه.","3:3":"وهذه أسسها سليمان لبناء بيت الله: الطول (بـالذراع على القياس الأول) ستون ذراعا والعرض عشرون ذراعا.","3:4":"والرواق الذي قدام الطول حسب عرض البيت عشرون ذراعا وارتفاعه مئة وعشرون وغشاه من داخل بذهب خالص.","3:5":"والبيت العظيم غشاه بخشب سرو غشاه بذهب خالص وجعل عليه نخيلا وسلاسل.","3:6":"ورصع البيت بحجارة كريمة للجمال. والذهب ذهب فروايم.","3:7":"وغشى البيت: أخشابه وأعتابه وحيطانه ومصاريعه بذهب ونقش كروبيم على الحيطان.","3:8":"وعمل بيت قدس الأقداس طوله حسب عرض البيت عشرون ذراعا وعرضه عشرون ذراعا وغشاه بذهب جيد ست مئة وزنة.","3:9":"وكان وزن المسامير خمسين شاقلا من ذهب وغشى العلالي بذهب.","3:10":"وعمل في بيت قدس الأقداس كروبين صناعة الصياغة وغشاهما بذهب.","3:11":"وأجنحة الكروبين طولها عشرون ذراعا الجناح الواحد خمس أذرع يمس حائط البيت والجناح الآخر خمس أذرع يمس جناح الكروب الآخر.","3:12":"وجناح الكروب الآخر خمس أذرع يمس حائط البيت والجناح الآخر خمس أذرع يتصل بجناح الكروب الآخر.","3:13":"وأجنحة هذين الكروبين منبسطة عشرون ذراعا وهما واقفان على أرجلهما ووجههما إلى داخل.","3:14":"وعمل الحجاب من أسمانجوني وأرجوان وقرمز وكتان وجعل عليه كروبيم.","3:15":"وعمل أمام البيت عمودين طولهما خمس وثلاثون ذراعا والتاجان اللذان على رأسيهما خمس أذرع.","3:16":"وعمل سلاسل كما في المحراب وجعلها على رأسي العمودين وعمل مئة رمانة وجعلها في السلاسل.","3:17":"وأوقف العمودين أمام الهيكل واحدا عن اليمين وواحدا عن اليسار ودعا اسم الأيمن [ياكين] واسم الأيسر [بوعز].","4:1":"وعمل مذبح نحاس طوله عشرون ذراعا وعرضه عشرون ذراعا وارتفاعه عشر أذرع.","4:2":"وعمل البحر مسبوكا عشر أذرع من شفته إلى شفته وكان مدورا مستديرا وارتفاعه خمس أذرع وخيط ثلاثون ذراعا يحيط بدائره.","4:3":"وشبه قثاء تحته مستديرا يحيط به على استدارته للذراع عشر تحيط بالبحر مستديرة والقثاء صفان قد سبكت بسبكه","4:4":"كان قائما على اثني عشر ثورا ثلاثة متجهة إلى الشمال وثلاثة متجهة إلى الغرب وثلاثة متجهة إلى الجنوب وثلاثة متجهة إلى الشرق والبحر عليها من فوق وجميع مؤخراتها إلى داخل.","4:5":"وسمكه شبر وشفته كعمل شفة كأس بزهر سوسن. يأخذ ويسع ثلاثة آلاف بث.","4:6":"وعمل عشر مراحض وجعل خمسا عن اليمين وخمسا عن اليسار للاغتسال فيها. كانوا يغسلون فيها ما يقربونه محرقة والبحر ليغتسل فيه الكهنة.","4:7":"وعمل منائر ذهب عشرا كرسمها وجعلها في الهيكل خمسا عن اليمين وخمسا عن اليسار.","4:8":"وعمل عشر موائد ووضعها في الهيكل خمسا عن اليمين وخمسا عن اليسار. وعمل مئة منضحة من ذهب.","4:9":"وعمل دار الكهنة والدار العظيمة ومصاريع الدار وغشى مصاريعها بنحاس.","4:10":"وجعل البحر إلى الجانب الأيمن إلى الشرق من جهة الجنوب.","4:11":"وعمل حورام القدور والرفوش والمناضح وانتهى حورام من عمل العمل الذي صنعه للملك سليمان في بيت الله:","4:12":"العمودين وكرتي التاجين على رأسي العمودين والشبكتين لتغطية كرتي التاجين اللذين على رأسي العمودين","4:13":"والرمانات الأربع مئة للشبكتين (صفي رمان للشبكة الواحدة لتغطية كرتي التاجين اللذين على العمودين).","4:14":"وعمل القواعد وعمل المراحض على القواعد","4:15":"والبحر الواحد والاثني عشر ثورا تحته","4:16":"والقدور والرفوش والمناشل وكل آنيتها عملها للملك سليمان [حورام أبي] لبيت الرب من نحاس مجلي.","4:17":"في غور الأردن سبكها الملك في أرض الخزف بين سكوت وصردة.","4:18":"وعمل سليمان كل هذه الآنية كثيرة جدا لأنه لم يتحقق وزن النحاس.","4:19":"وعمل سليمان كل الآنية التي لبيت الله ومذبح الذهب والموائد وعليها خبز الوجوه","4:20":"والمنائر وسرجها لتتقد حسب المرسوم أمام المحراب من ذهب خالص","4:21":"والأزهار والسرج والملاقط من ذهب. وهو ذهب كامل.","4:22":"والمقاص والمناضح والصحون والمجامر من ذهب خالص. وباب البيت ومصاريعه الداخلية لقدس الأقداس ومصاريع بيت الهيكل من ذهب.","5:1":"وكمل جميع العمل الذي عمله سليمان لبيت الرب. وأدخل سليمان أقداس داود أبيه. والفضة والذهب وجميع الآنية جعلها في خزائن بيت الله.","5:2":"حينئذ جمع سليمان شيوخ إسرائيل وكل رؤوس الأسباط رؤساء الآباء لبني إسرائيل إلى أورشليم لإصعاد تابوت عهد الرب من مدينة داود (هي صهيون).","5:3":"فاجتمع إلى الملك جميع رجال إسرائيل في العيد الذي في الشهر السابع.","5:4":"وجاء جميع شيوخ إسرائيل. وحمل اللاويون التابوت","5:5":"وأصعدوا التابوت وخيمة الاجتماع مع جميع آنية القدس التي في الخيمة أصعدها الكهنة واللاويون.","5:6":"والملك سليمان وكل جماعة إسرائيل المجتمعين إليه أمام التابوت كانوا يذبحون غنما وبقرا ما لا يحصى ولا يعد من الكثرة.","5:7":"وأدخل الكهنة تابوت عهد الرب إلى مكانه في محراب البيت في قدس الأقداس إلى تحت جناحي الكروبين.","5:8":"وكان الكروبان باسطين أجنحتهما على موضع التابوت. وظلل الكروبان التابوت وعصيه من فوق.","5:9":"وجذبوا العصي فتراءت رؤوس العصي من التابوت أمام المحراب ولم تر خارجا وهي هناك إلى هذا اليوم.","5:10":"لم يكن في التابوت إلا اللوحان اللذان وضعهما موسى في حوريب حين عاهد الرب بني إسرائيل عند خروجهم من مصر.","5:11":"وكان لما خرج الكهنة من القدس. (لأن جميع الكهنة الموجودين تقدسوا. لم تلاحظ الفرق).","5:12":"واللاويون المغنون أجمعون: آساف وهيمان ويدوثون وبنوهم وإخوتهم لابسين كتانا بالصنوج والرباب والعيدان واقفين شرقي المذبح ومعهم من الكهنة مئة وعشرون ينفخون في الأبواق.","5:13":"وكان لما صوت المبوقون والمغنون كواحد صوتا واحدا لتسبيح الرب وحمده ورفعوا صوتا بالأبواق والصنوج وآلات الغناء والتسبيح للرب لأنه صالح لأن إلى الأبد رحمته أن بيت الرب امتلأ سحابا.","5:14":"ولم يستطع الكهنة أن يقفوا للخدمة بسبب السحاب لأن مجد الرب ملأ بيت الله.","6:1":"حينئذ قال سليمان: [قال الرب إنه يسكن في الضباب.","6:2":"وأنا بنيت لك بيت سكنى مكانا لسكناك إلى الأبد].","6:3":"وحول الملك وجهه وبارك كل جمهور إسرائيل وكل جمهور إسرائيل واقف.","6:4":"وقال: [مبارك الرب إله إسرائيل الذي كلم بفمه داود أبي وأكمل بيديه قائلا:","6:5":"منذ يوم أخرجت شعبي من أرض مصر لم أختر مدينة من جميع أسباط إسرائيل لبناء بيت ليكون اسمي هناك ولا اخترت رجلا يكون رئيسا لشعبي إسرائيل.","6:6":"بل اخترت أورشليم ليكون اسمي فيها واخترت داود ليكون على شعبي إسرائيل.","6:7":"وكان في قلب داود أبي أن يبني بيتا لاسم الرب إله إسرائيل","6:8":"فقال الرب لداود أبي: من أجل أنه كان في قلبك أن تبني بيتا لاسمي قد أحسنت بكون ذلك في قلبك.","6:9":"إلا أنك أنت لا تبني البيت بل ابنك الخارج من صلبك هو يبني البيت لاسمي.","6:10":"وأقام الرب كلامه الذي تكلم به وقد قمت أنا مكان داود أبي وجلست على كرسي إسرائيل كما تكلم الرب وبنيت البيت لاسم الرب إله إسرائيل.","6:11":"ووضعت هناك التابوت الذي فيه عهد الرب الذي قطعه مع بني إسرائيل].","6:12":"ووقف أمام مذبح الرب تجاه كل جماعة إسرائيل وبسط يديه.","6:13":"(لأن سليمان صنع منبرا من نحاس وجعله في وسط الدار طوله خمس أذرع وعرضه خمس أذرع وارتفاعه ثلاث أذرع ووقف عليه ثم جثا على ركبتيه تجاه كل جماعة إسرائيل وبسط يديه نحو السماء)","6:14":"وقال: [أيها الرب إله إسرائيل لا إله مثلك في السماء والأرض حافظ العهد والرحمة لعبيدك السائرين أمامك بكل قلوبهم.","6:15":"الذي قد حفظت لعبدك داود أبي ما كلمته به فتكلمت بفمك وأكملت بيدك كهذا اليوم.","6:16":"والآن أيها الرب إله إسرائيل احفظ لعبدك داود أبي ما كلمته به قائلا: لا يعدم لك أمامي رجل يجلس على كرسي إسرائيل إن حفظ بنوك طرقهم حتى يسيروا في شريعتي كما سرت أنت أمامي.","6:17":"والآن أيها الرب إله إسرائيل فليتحقق كلامك الذي كلمت به عبدك داود.","6:18":"لأنه هل يسكن الله حقا مع الإنسان على الأرض؟ هوذا السماوات وسماء السماوات لا تسعك فكم بالأقل هذا البيت الذي بنيت!","6:19":"فالتفت إلى صلاة عبدك وإلى تضرعه أيها الرب إلهي واسمع الصراخ والصلاة التي يصليها عبدك أمامك.","6:20":"لتكون عيناك مفتوحتين على هذا البيت نهارا وليلا على الموضع الذي قلت إنك تضع اسمك فيه لتسمع الصلاة التي يصليها عبدك في هذا الموضع","6:21":"واسمع تضرعات عبدك وشعبك إسرائيل الذين يصلون في هذا الموضع واسمع أنت من موضع سكناك من السماء وإذا سمعت فاغفر.","6:22":"إن أخطأ أحد إلى صاحبه ووضع عليه حلف ليحلفه وجاء الحلف أمام مذبحك في هذا البيت","6:23":"فاسمع أنت من السماء واعمل واقض بين عبيدك إذ تعاقب المذنب فتجعل طريقه على رأسه وتبرر البار إذ تعطيه حسب بره.","6:24":"وإن انكسر شعبك إسرائيل أمام العدو لأنهم أخطأوا إليك ثم رجعوا واعترفوا باسمك وصلوا وتضرعوا أمامك نحو هذا البيت","6:25":"فاسمع أنت من السماء واغفر خطية شعبك إسرائيل وأرجعهم إلى الأرض التي أعطيتها لهم ولآبائهم.","6:26":"[إذا أغلقت السماء ولم يكن مطر لأنهم أخطأوا إليك ثم صلوا في هذا المكان واعترفوا باسمك ورجعوا عن خطيتهم لأنك ضايقتهم","6:27":"فاسمع أنت من السماء واغفر خطية عبيدك وشعبك إسرائيل فتعلمهم الطريق الصالح الذي يسلكون فيه وأعط مطرا على أرضك التي أعطيتها لشعبك ميراثا.","6:28":"إذا صار في الأرض جوع إذا صار وبأ أو لفح أو يرقان أو جراد أو جردم أو إذا حاصرهم أعداؤهم في أرض مدنهم في كل ضربة وكل مرض","6:29":"فكل صلاة وكل تضرع تكون من أي إنسان كان أو من كل شعبك إسرائيل الذين يعرفون كل واحد ضربته ووجعه فيبسط يديه نحو هذا البيت","6:30":"فاسمع أنت من السماء مكان سكناك واغفر وأعط كل إنسان حسب كل طرقه كما تعرف قلبه. لأنك أنت وحدك تعرف قلوب بني البشر.","6:31":"ليخافوك ويسيروا في طرقك كل الأيام التي يحيون فيها على وجه الأرض التي أعطيت لآبائنا.","6:32":"وكذلك الأجنبي الذي ليس هو من شعبك إسرائيل وقد جاء من أرض بعيدة من أجل اسمك العظيم ويدك القوية وذراعك الممدودة فمتى جاءوا وصلوا في هذا البيت","6:33":"فاسمع أنت من السماء مكان سكناك وافعل حسب كل ما يدعوك به الأجنبي ليعلم كل شعوب الأرض اسمك فيخافوك كشعبك إسرائيل وليعلموا أن اسمك قد دعي على هذا البيت الذي بنيت.","6:34":"[إذا خرج شعبك لمحاربة أعدائه في الطريق الذي ترسلهم فيه وصلوا إليك نحو هذه المدينة التي اخترتها والبيت الذي بنيت لاسمك","6:35":"فاسمع من السماء صلاتهم وتضرعهم واقض قضاءهم.","6:36":"إذا أخطأوا إليك (لأنه ليس إنسان لا يخطئ) وغضبت عليهم ودفعتهم أمام العدو وسباهم سابوهم إلى أرض بعيدة أو قريبة","6:37":"فإذا ردوا إلى قلوبهم في الأرض التي يسبون إليها ورجعوا وتضرعوا إليك في أرض سبيهم قائلين: قد أخطأنا وعوجنا وأذنبنا","6:38":"ورجعوا إليك من كل قلوبهم ومن كل أنفسهم في أرض سبيهم التي سبوهم إليها وصلوا نحو أرضهم التي أعطيتها لآبائهم والمدينة التي اخترت والبيت الذي بنيت لاسمك","6:39":"فاسمع من السماء من مكان سكناك صلاتهم وتضرعاتهم واقض قضاءهم واغفر لشعبك ما أخطأوا به إليك.","6:40":"الآن يا إلهي لتكن عيناك مفتوحتين وأذناك مصغيتين لصلاة هذا المكان.","6:41":"والآن قم أيها الرب الإله إلى راحتك أنت وتابوت عزك. كهنتك أيها الرب الإله يلبسون الخلاص وأتقياؤك يبتهجون بالخير.","6:42":"أيها الرب الإله لا ترد وجه مسيحك. اذكر مراحم داود عبدك].","7:1":"ولما انتهى سليمان من الصلاة نزلت النار من السماء وأكلت المحرقة والذبائح وملأ مجد الرب البيت.","7:2":"ولم يستطع الكهنة أن يدخلوا بيت الرب لأن مجد الرب ملأ بيت الرب.","7:3":"وكان جميع بني إسرائيل ينظرون عند نزول النار ومجد الرب على البيت وخروا على وجوههم إلى الأرض على البلاط المجزع وسجدوا وحمدوا الرب لأنه صالح وإلى الأبد رحمته.","7:4":"ثم إن الملك وكل الشعب ذبحوا ذبائح أمام الرب.","7:5":"وذبح الملك سليمان ذبائح من البقر: اثنين وعشرين ألفا ومن الغنم مئة وعشرين ألفا ودشن الملك وكل الشعب بيت الله.","7:6":"وكان الكهنة واقفين على محارسهم واللاويون بآلات غناء الرب التي عملها داود الملك لأجل حمد الرب [لأن إلى الأبد رحمته] حين سبح داود بها والكهنة ينفخون في الأبواق مقابلهم وكل إسرائيل واقف.","7:7":"وقدس سليمان وسط الدار التي أمام بيت الرب لأنه قرب هناك المحرقات وشحم ذبائح السلامة لأن مذبح النحاس الذي عمله سليمان لم يكف لأن يسع المحرقات والتقدمات والشحم.","7:8":"وعيد سليمان العيد في ذلك الوقت سبعة أيام وكل إسرائيل معه وجمهور عظيم جدا من مدخل حماة إلى وادي مصر.","7:9":"وعملوا في اليوم الثامن اعتكافا لأنهم عملوا تدشين المذبح سبعة أيام والعيد سبعة أيام.","7:10":"وفي اليوم الثالث والعشرين من الشهر السابع صرف الشعب إلى خيامهم فرحين وطيبي القلوب لأجل الخير الذي عمله الرب لداود ولسليمان ولإسرائيل شعبه.","7:11":"وأكمل سليمان بيت الرب وبيت الملك. وكل ما خطر ببال سليمان أن يعمله في بيت الرب وفي بيته نجح فيه.","7:12":"وتراءى الرب لسليمان ليلا وقال له: [قد سمعت صلاتك واخترت هذا المكان لي بيت ذبيحة.","7:13":"إن أغلقت السماء ولم يكن مطر وإن أمرت الجراد أن يأكل الأرض وإن أرسلت وبأ على شعبي","7:14":"فإذا تواضع شعبي الذين دعي اسمي عليهم وصلوا وطلبوا وجهي ورجعوا عن طرقهم الرديئة فإني أسمع من السماء وأغفر خطيتهم وأبرئ أرضهم.","7:15":"الآن عيناي تكونان مفتوحتين وأذناي مصغيتين إلى صلاة هذا المكان.","7:16":"والآن قد اخترت وقدست هذا البيت ليكون اسمي فيه إلى الأبد وتكون عيناي وقلبي هناك كل الأيام.","7:17":"وأنت إن سلكت أمامي كما سلك داود أبوك وعملت حسب كل ما أمرتك به وحفظت فرائضي وأحكامي","7:18":"فإني أثبت كرسي ملكك كما عاهدت داود أباك قائلا: لا يعدم لك رجل يتسلط على إسرائيل.","7:19":"ولكن إن انقلبتم وتركتم فرائضي ووصاياي التي جعلتها أمامكم وذهبتم وعبدتم آلهة أخرى وسجدتم لها","7:20":"فإني أقلعهم من أرضي التي أعطيتهم إياها وهذا البيت الذي قدسته لاسمي أطرحه من أمامي وأجعله مثلا وهزأة في جميع الشعوب.","7:21":"وهذا البيت الذي كان مرتفعا كل من يمر به يتعجب ويقول: لماذا عمل الرب هكذا لهذه الأرض ولهذا البيت؟","7:22":"فيقولون: من أجل أنهم تركوا الرب إله آبائهم الذي أخرجهم من أرض مصر وتمسكوا بآلهة أخرى وسجدوا لها وعبدوها لذلك جلب عليهم كل هذا الشر].","8:1":"وبعد نهاية عشرين سنة بعد أن بنى سليمان بيت الرب وبيته","8:2":"بنى سليمان المدن التي أعطاها حورام لسليمان وأسكن فيها بني إسرائيل.","8:3":"وذهب سليمان إلى حماة صوبة وقوي عليها.","8:4":"وبنى تدمر في البرية وجميع مدن المخازن التي بناها في حماة.","8:5":"وبنى بيت حورون العليا وبيت حورون السفلى مدنا حصينة بأسوار وأبواب وعوارض.","8:6":"وبعلة وكل مدن المخازن التي كانت لسليمان وجميع مدن المركبات ومدن الفرسان وكل مرغوب سليمان الذي رغب أن يبنيه في أورشليم وفي لبنان وفي كل أرض سلطانه.","8:7":"أما جميع الشعب الباقي من الحثيين والأموريين والفرزيين والحويين واليبوسيين الذين ليسوا من إسرائيل","8:8":"من بينهم الذين بقوا بعدهم في الأرض الذين لم يفنهم بنو إسرائيل فجعل سليمان عليهم سخرة إلى هذا اليوم.","8:9":"وأما بنو إسرائيل فلم يجعل سليمان منهم عبيدا لشغله لأنهم رجال القتال ورؤساء قواده ورؤساء مركباته وفرسانه.","8:10":"وهؤلاء رؤساء الموكلين الذين للملك سليمان مئتان وخمسون المتسلطون على الشعب.","8:11":"وأما بنت فرعون فأصعدها سليمان من مدينة داود إلى البيت الذي بناه لها لأنه قال: [لا تسكن امرأة لي في بيت داود ملك إسرائيل لأن الأماكن التي دخل إليها تابوت الرب إنما هي مقدسة].","8:12":"حينئذ أصعد سليمان محرقات للرب على مذبح الرب الذي بناه قدام الرواق.","8:13":"أمر كل يوم بيومه من المحرقات حسب وصية موسى في السبوت والأهلة والمواسم ثلاث مرات في السنة في عيد الفطير وعيد الأسابيع وعيد المظال.","8:14":"وأوقف حسب قضاء داود أبيه فرق الكهنة على خدمتهم واللاويين على حراساتهم (للتسبيح والخدمة أمام الكهنة) عمل كل يوم بيومه والبوابين حسب فرقهم على كل باب. لأنه هكذا هي وصية داود رجل الله.","8:15":"ولم يحيدوا عن وصية الملك على الكهنة واللاويين في كل أمر وفي الخزائن.","8:16":"فتهيأ كل عمل سليمان إلى يوم تأسيس بيت الرب وإلى نهايته. فكمل بيت الرب.","8:17":"حينئذ ذهب سليمان إلى عصيون جابر وإلى أيلة على شاطئ البحر في أرض أدوم.","8:18":"وأرسل له حورام بيد عبيده سفنا وعبيدا يعرفون البحر فأتوا مع عبيد سليمان إلى أوفير وأخذوا من هناك أربع مئة وخمسين وزنة ذهب وأتوا بها إلى الملك سليمان.","9:1":"وسمعت ملكة سبا بخبر سليمان فأتت لتمتحن سليمان بمسائل إلى أورشليم بموكب عظيم جدا وجمال حاملة أطيابا وذهبا بكثرة وحجارة كريمة فأتت إلى سليمان وكلمته عن كل ما في قلبها.","9:2":"فأخبرها سليمان بكل كلامها. ولم يخف عن سليمان أمر إلا وأخبرها به.","9:3":"فلما رأت ملكة سبا حكمة سليمان والبيت الذي بناه","9:4":"وطعام مائدته ومجلس عبيده وموقف خدامه وملابسهم وسقاته وملابسهم ومحرقاته التي كان يصعدها في بيت الرب لم تبق فيها روح بعد.","9:5":"فقالت للملك: [صحيح الخبر الذي سمعته في أرضي عن أمورك وعن حكمتك!","9:6":"ولم أصدق كلامهم حتى جئت وأبصرت عيناي فهوذا لم أخبر بنصف كثرة حكمتك. زدت على الخبر الذي سمعته.","9:7":"فطوبى لرجالك وطوبى لعبيدك هؤلاء الواقفين أمامك دائما والسامعين حكمتك.","9:8":"ليكن مباركا الرب إلهك الذي سر بك وجعلك على كرسيه ملكا للرب إلهك. لأن إلهك أحب إسرائيل ليثبته إلى الأبد قد جعلك عليهم ملكا لتجري حكما وعدلا].","9:9":"وأهدت للملك مئة وعشرين وزنة ذهب وأطيابا كثيرة جدا وحجارة كريمة ولم يكن مثل ذلك الطيب الذي أهدته ملكة سبا للملك سليمان.","9:10":"وكذا عبيد حورام وعبيد سليمان الذين جلبوا ذهبا من أوفير أتوا بخشب الصندل وحجارة كريمة.","9:11":"وعمل الملك خشب الصندل درجا لبيت الرب وبيت الملك وأعوادا وربابا ولم ير مثلها قبل في أرض يهوذا.","9:12":"وأعطى الملك سليمان ملكة سبا كل مشتهاها الذي طلبت فضلا عما أتت به إلى الملك. فانصرفت وذهبت إلى أرضها هي وعبيدها.","9:13":"وكان وزن الذهب الذي جاء سليمان في سنة واحدة ست مئة وستا وستين وزنة ذهب","9:14":"فضلا عن الذي جاء به التجار والمستبضعون. وكل ملوك العرب وولاة الأرض كانوا يأتون بذهب وفضة إلى سليمان.","9:15":"وعمل الملك سليمان مئتي ترس من ذهب مطرق خص الترس الواحد ست مئة شاقل من الذهب المطرق","9:16":"وثلاث مئة مجن من ذهب مطرق خص المجن الواحد ثلاث مئة شاقل من الذهب. وجعلها الملك في بيت وعر لبنان.","9:17":"وعمل الملك كرسيا عظيما من عاج وغشاه بذهب خالص.","9:18":"وللكرسي ست درجات. وللكرسي موطئ من ذهب كلها متصلة ويدان من هنا ومن هناك على مكان الجلوس وأسدان واقفان بجانب اليدين.","9:19":"واثنا عشر أسدا واقفة هناك على الدرجات الست من هنا ومن هناك. لم يعمل مثله في جميع الممالك.","9:20":"وجميع آنية شرب الملك سليمان من ذهب وجميع آنية بيت وعر لبنان من ذهب خالص. لم تحسب الفضة شيئا في أيام سليمان","9:21":"لأن سفن الملك كانت تسير إلى ترشيش مع عبيد حورام وكانت سفن ترشيش تأتي مرة في كل ثلاث سنين حاملة ذهبا وفضة وعاجا وقرودا وطواويس.","9:22":"فتعظم الملك سليمان على كل ملوك الأرض في الغنى والحكمة.","9:23":"وكان جميع ملوك الأرض يلتمسون وجه سليمان ليسمعوا حكمته التي جعلها الله في قلبه.","9:24":"وكانوا يأتون كل واحد بهديته بآنية فضة وآنية ذهب وحلل وسلاح وأطياب وخيل وبغال سنة فسنة.","9:25":"وكان لسليمان أربعة آلاف مذود خيل ومركبات واثنا عشر ألف فارس فجعلها في مدن المركبات ومع الملك في أورشليم.","9:26":"وكان متسلطا على جميع الملوك من النهر إلى أرض الفلسطينيين وإلى تخوم مصر.","9:27":"وجعل الملك الفضة في أورشليم مثل الحجارة وجعل الأرز مثل الجميز الذي في السهل في الكثرة.","9:28":"وكان مخرج خيل سليمان من مصر ومن جميع الأراضي.","9:29":"وبقية أمور سليمان الأولى والأخيرة مكتوبة في أخبار ناثان النبي وفي نبوة أخيا الشيلوني وفي رؤى يعدو الرائي على يربعام بن نباط.","9:30":"وملك سليمان في أورشليم على كل إسرائيل أربعين سنة.","9:31":"ثم اضطجع سليمان مع آبائه فدفنوه في مدينة داود أبيه. وملك رحبعام ابنه عوضا عنه.","10:1":"وذهب رحبعام إلى شكيم لأنه جاء إلى شكيم كل إسرائيل ليملكوه.","10:2":"ولما سمع يربعام بن نباط (وهو في مصر حيث هرب من وجه سليمان الملك) رجع يربعام من مصر.","10:3":"فأرسلوا ودعوه فأتى يربعام وكل إسرائيل وقالوا لرحبعام:","10:4":"[إن أباك قسى نيرنا فالآن خفف من عبودية أبيك القاسية ومن نيره الثقيل الذي جعله علينا فنخدمك].","10:5":"فقال لهم: [ارجعوا إلي بعد ثلاثة أيام]. فذهب الشعب.","10:6":"فاستشار الملك رحبعام الشيوخ الذين كانوا يقفون أمام سليمان أبيه وهو حي قائلا: [كيف تشيرون أن أرد جوابا على هذا الشعب؟]","10:7":"فقالوا: [إن كنت صالحا نحو هذا الشعب وأرضيتهم وكلمتهم كلاما حسنا يكونون لك عبيدا كل الأيام].","10:8":"فترك مشورة الشيوخ التي أشاروا بها عليه واستشار الأحداث الذين نشأوا معه ووقفوا أمامه","10:9":"وسألهم: [بماذا تشيرون أنتم فنرد جوابا على هذا الشعب الذين كلموني قائلين: خفف من النير الذي جعله علينا أبوك؟]","10:10":"فأجاب الأحداث الذين نشأوا معه: [هكذا تقول للشعب الذين قالوا إن أباك ثقل نيرنا وأما أنت فخفف عنا: إن خنصري أغلظ من وسط أبي.","10:11":"والآن أبي حملكم نيرا ثقيلا وأنا أزيد على نيركم. أبي أدبكم بالسياط وأما أنا فبالعقارب].","10:12":"فجاء يربعام وجميع الشعب إلى رحبعام في اليوم الثالث كما أمر الملك: [ارجعوا إلي في اليوم الثالث].","10:13":"فأجابهم الملك بقساوة وترك الملك رحبعام مشورة الشيوخ","10:14":"وكلمهم حسب مشورة الأحداث قائلا: [أبي ثقل نيركم وأنا أزيد عليه. أبي أدبكم بالسياط وأما أنا فبالعقارب].","10:15":"ولم يسمع الملك للشعب لأن السبب كان من قبل الله ليقيم الرب كلامه الذي تكلم به عن يد أخيا الشيلوني إلى يربعام بن نباط.","10:16":"فلما رأى كل إسرائيل أن الملك لم يسمع لهم قال الشعب للملك: [أي قسم لنا في داود! ولا نصيب لنا في ابن يسى. كل واحد إلى خيمته يا إسرائيل. الآن انظر إلى بيتك يا داود!] وذهب كل إسرائيل إلى خيامهم.","10:17":"وأما بنو إسرائيل الساكنون في مدن يهوذا فملك عليهم رحبعام.","10:18":"ثم أرسل الملك رحبعام هدورام الذي على التسخير فرجمه بنو إسرائيل بالحجارة فمات. فبادر الملك رحبعام وصعد إلى المركبة ليهرب إلى أورشليم","10:19":"فعصى إسرائيل بيت داود إلى هذا اليوم.الأصحاح الحادي عشر","11:1":"ولما جاء رحبعام إلى أورشليم جمع من بيت يهوذا وبنيامين مئة وثمانين ألف مختار محارب ليحارب إسرائيل ليرد الملك إلى رحبعام.","11:2":"وكان كلام الرب إلى شمعيا رجل الله","11:3":"[قل لرحبعام بن سليمان ملك يهوذا وكل إسرائيل في يهوذا وبنيامين:","11:4":"هكذا قال الرب: لا تصعدوا ولا تحاربوا إخوتكم. ارجعوا كل واحد إلى بيته لأنه من قبلي صار هذا الأمر] فسمعوا لكلام الرب ورجعوا عن الذهاب ضد يربعام.","11:5":"وأقام رحبعام في أورشليم وبنى مدنا للحصار في يهوذا.","11:6":"فبنى بيت لحم وعيطام وتقوع","11:7":"وبيت صور وسوكو وعدلام","11:8":"وجت ومريشة وزيف","11:9":"وأدورايم ولخيش وعزيقة","11:10":"وصرعة وأيلون وحبرون التي في يهوذا وبنيامين مدنا حصينة.","11:11":"وشدد الحصون وجعل فيها قوادا وخزائن مأكل وزيت وخمر","11:12":"وأتراسا في كل مدينة ورماحا وشددها كثيرا جدا وكان له يهوذا وبنيامين.","11:13":"والكهنة واللاويون الذين في كل إسرائيل مثلوا بين يديه من جميع تخومهم","11:14":"لأن اللاويين تركوا مراعيهم وأملاكهم وانطلقوا إلى يهوذا وأورشليم لأن يربعام وبنيه رفضوهم من أن يكهنوا للرب","11:15":"وأقام لنفسه كهنة للمرتفعات وللتيوس وللعجول التي عمل.","11:16":"وبعدهم جاء إلى أورشليم من جميع أسباط إسرائيل الذين وجهوا قلوبهم إلى طلب الرب إله إسرائيل ليذبحوا للرب إله آبائهم.","11:17":"وشددوا مملكة يهوذا وقووا رحبعام بن سليمان ثلاث سنين لأنهم ساروا في طريق داود وسليمان ثلاث سنين.","11:18":"واتخذ رحبعام لنفسه امرأة: محلة بنت يريموث بن داود وأبيجايل بنت أليآب بن يسى.","11:19":"فولدت له بنين: يعوش وشمريا وزاهم","11:20":"ثم بعدها أخذ معكة بنت أبشالوم فولدت له أبيا وعتاي وزيزا وشلوميث.","11:21":"وأحب رحبعام معكة بنت أبشالوم أكثر من جميع نسائه وسراريه لأنه اتخذ ثماني عشرة امرأة وستين سرية وولد ثمانية وعشرين ابنا وستين ابنة.","11:22":"وأقام رحبعام أبيا ابن معكة رأسا وقائدا بين إخوته ليملكه.","11:23":"وكان فهيما وفرق من كل بنيه في جميع أراضي يهوذا وبنيامين في كل المدن الحصينة وأعطاهم زادا بكثرة. وطلب نساء كثيرة.","12:1":"ولما تثبتت مملكة رحبعام وتشددت ترك شريعة الرب هو وكل إسرائيل معه.","12:2":"وفي السنة الخامسة للملك رحبعام صعد شيشق ملك مصر على أورشليم - لأنهم خانوا الرب -","12:3":"بألف ومئتي مركبة وستين ألف فارس ولم يكن عدد للشعب الذين جاءوا معه من مصر: لوبيين وسكيين وكوشيين.","12:4":"وأخذ المدن الحصينة التي ليهوذا وأتى إلى أورشليم.","12:5":"فجاء شمعيا النبي إلى رحبعام ورؤساء يهوذا الذين اجتمعوا في أورشليم من وجه شيشق وقال لهم: [هكذا قال الرب: أنتم تركتموني وأنا أيضا تركتكم ليد شيشق].","12:6":"فتذلل رؤساء إسرائيل والملك وقالوا: [بار هو الرب].","12:7":"فلما رأى الرب أنهم تذللوا كان كلام الرب إلى شمعيا: [قد تذللوا فلا أهلكهم بل أعطيهم قليلا من النجاة ولا ينصب غضبي على أورشليم بيد شيشق","12:8":"لكنهم يكونون له عبيدا ويعلمون خدمتي وخدمة ممالك الأراضي].","12:9":"فصعد شيشق ملك مصر على أورشليم وأخذ خزائن بيت الرب وخزائن بيت الملك أخذ الجميع وأخذ أتراس الذهب التي عملها سليمان.","12:10":"فعمل الملك رحبعام عوضا عنها أتراس نحاس وسلمها إلى أيدي رؤساء السعاة الحافظين باب بيت الملك.","12:11":"وكان إذا دخل الملك بيت الرب يأتي السعاة ويحملونها ثم يرجعونها إلى غرفة السعاة.","12:12":"ولما تذلل ارتد عنه غضب الرب فلم يهلكه تماما. وكذلك كان في يهوذا أمور حسنة.","12:13":"فتشدد الملك رحبعام في أورشليم وملك لأن رحبعام كان ابن إحدى وأربعين سنة حين ملك وملك سبع عشرة سنة في أورشليم المدينة التي اختارها الرب ليضع اسمه فيها دون جميع أسباط إسرائيل. واسم أمه نعمة العمونية.","12:14":"وعمل الشر لأنه لم يهيئ قلبه لطلب الرب.","12:15":"وأمور رحبعام الأولى والأخيرة مكتوبة في أخبار شمعيا النبي وعدو الرائي عن الانتساب. وكانت حروب بين رحبعام ويربعام كل الأيام.","12:16":"ثم اضطجع رحبعام مع آبائه ودفن في مدينة داود وملك أبيا ابنه عوضا عنه.","13:1":"في السنة الثامنة عشرة للملك يربعام ملك أبيا على يهوذا.","13:2":"ملك ثلاث سنين في أورشليم. واسم أمه ميخايا بنت أوريئيل من جبعة. وكانت حرب بين أبيا ويربعام.","13:3":"وابتدأ أبيا في الحرب بجيش من جبابرة القتال أربع مئة ألف رجل مختار ويربعام اصطف لمحاربته بثمان مئة ألف رجل مختار جبابرة بأس.","13:4":"وقام أبيا على جبل صمارايم الذي في جبل أفرايم وقال: [اسمعوني يا يربعام وكل إسرائيل.","13:5":"أما لكم أن تعرفوا أن الرب إله إسرائيل أعطى الملك على إسرائيل لداود إلى الأبد ولبنيه بعهد ملح؟","13:6":"فقام يربعام بن نباط عبد سليمان بن داود وعصى سيده.","13:7":"فاجتمع إليه رجال بطالون بنو بليعال وتشددوا على رحبعام بن سليمان وكان رحبعام فتى رقيق القلب فلم يثبت أمامهم.","13:8":"والآن أنتم تقولون إنكم تثبتون أمام مملكة الرب بيد بني داود وأنتم جمهور كثير ومعكم عجول ذهب قد عملها يربعام لكم آلهة.","13:9":"أما طردتم كهنة الرب بني هارون واللاويين وعملتم لأنفسكم كهنة كشعوب الأراضي كل من أتى ليملأ يده بثور ابن بقر وسبعة كباش صار كاهنا للذين ليسوا آلهة!","13:10":"وأما نحن فالرب هو إلهنا ولم نتركه. والكهنة الخادمون الرب هم بنو هارون واللاويون في العمل","13:11":"ويوقدون للرب محرقات كل صباح ومساء وبخور أطياب وخبز الوجوه على المائدة الطاهرة ومنارة الذهب وسرجها للإيقاد كل مساء لأننا نحن حارسون حراسة الرب إلهنا. وأما أنتم فقد تركتموه.","13:12":"وهوذا معنا الله رئيسا وكهنته وأبواق الهتاف للهتاف عليكم. فيا بني إسرائيل لا تحاربوا الرب إله آبائكم لأنكم لا تفلحون].","13:13":"ولكن يربعام جعل الكمين يدور ليأتي من خلفهم. فكانوا أمام يهوذا والكمين خلفهم.","13:14":"فالتفت يهوذا وإذا الحرب عليهم من قدام ومن خلف. فصرخوا إلى الرب وبوق الكهنة بالأبواق","13:15":"وهتف رجال يهوذا. ولما هتف رجال يهوذا ضرب الله يربعام وكل إسرائيل أمام أبيا ويهوذا.","13:16":"فانهزم بنو إسرائيل من أمام يهوذا ودفعهم الله ليدهم.","13:17":"وضربهم أبيا وقومه ضربة عظيمة فسقط قتلى من إسرائيل خمس مئة ألف رجل مختار.","13:18":"فذل بنو إسرائيل في ذلك الوقت وتشجع بنو يهوذا لأنهم اتكلوا على الرب إله آبائهم.","13:19":"وطارد أبيا يربعام وأخذ منه مدنا: بيت إيل وقراها ويشانة وقراها وعفرون وقراها.","13:20":"ولم يقو يربعام بعد في أيام أبيا فضربه الرب ومات.","13:21":"وتشدد أبيا واتخذ لنفسه أربع عشرة امرأة وولد اثنين وعشرين ابنا وست عشرة بنتا.","13:22":"وبقية أمور أبيا وطرقه وأقواله مكتوبة في مدرس النبي عدو.","14:1":"ثم اضطجع أبيا مع آبائه فدفنوه في مدينة داود وملك آسا ابنه عوضا عنه. في أيامه استراحت الأرض عشر سنين.","14:2":"وعمل آسا ما هو صالح ومستقيم في عيني الرب إلهه.","14:3":"ونزع المذابح الغريبة والمرتفعات وكسر التماثيل وقطع السواري","14:4":"وقال ليهوذا أن يطلبوا الرب إله آبائهم وأن يعملوا حسب الشريعة والوصية.","14:5":"ونزع من كل مدن يهوذا المرتفعات وتماثيل الشمس واستراحت المملكة أمامه.","14:6":"وبنى مدنا حصينة في يهوذا لأن الأرض استراحت ولم تكن عليه حرب في تلك السنين لأن الرب أراحه.","14:7":"وقال ليهوذا: [لنبن هذه المدن ونحوطها بأسوار وأبراج وأبواب وعوارض ما دامت الأرض أمامنا لأننا قد طلبنا الرب إلهنا. طلبناه فأراحنا من كل جهة]. فبنوا ونجحوا.","14:8":"وكان لآسا جيش يحملون أتراسا ورماحا من يهوذا ثلاث مئة ألف ومن بنيامين من الذين يحملون الأتراس ويشدون القسي مئتان وثمانون ألفا. كل هؤلاء جبابرة بأس.","14:9":"فخرج إليهم زارح الكوشي بجيش ألف ألف وبمركبات ثلاث مئة وأتى إلى مريشة.","14:10":"وخرج آسا للقائه واصطفوا للقتال في وادي صفاتة عند مريشة.","14:11":"ودعا آسا الرب إلهه: [أيها الرب ليس فرقا عندك أن تساعد الكثيرين ومن ليس لهم قوة. فساعدنا أيها الرب إلهنا لأننا عليك اتكلنا وباسمك قدمنا على هذا الجيش. أيها الرب أنت إلهنا. لا يقو عليك إنسان].","14:12":"فضرب الرب الكوشيين أمام آسا وأمام يهوذا فهرب الكوشيون.","14:13":"وطردهم آسا والشعب الذي معه إلى جرار وسقط من الكوشيين حتى لم يكن لهم حي لأنهم انكسروا أمام الرب وأمام جيشه. فحملوا غنيمة كثيرة جدا.","14:14":"وضربوا جميع المدن التي حول جرار لأن رعب الرب كان عليهم ونهبوا كل المدن لأنه كان فيها نهب كثير.","14:15":"وضربوا أيضا خيام الماشية وساقوا غنما كثيرا وجمالا ثم رجعوا إلى أورشليم.","15:1":"وكان روح الله على عزريا بن عوديد","15:2":"فخرج للقاء آسا وقال له: [اسمعوا لي يا آسا وجميع يهوذا وبنيامين. الرب معكم ما كنتم معه وإن طلبتموه يوجد لكم وإن تركتموه يترككم.","15:3":"ولإسرائيل أيام كثيرة بلا إله حق وبلا كاهن معلم وبلا شريعة.","15:4":"ولكن لما رجعوا عندما تضايقوا إلى الرب إله إسرائيل وطلبوه وجد لهم.","15:5":"وفي تلك الأزمان لم يكن أمان للخارج ولا للداخل لأن اضطرابات كثيرة كانت على كل سكان الأراضي.","15:6":"فأفنيت أمة بأمة ومدينة بمدينة لأن الله أزعجهم بكل ضيق.","15:7":"فتشددوا أنتم ولا ترتخ أيديكم لأن لعملكم أجرا].","15:8":"فلما سمع آسا هذا الكلام ونبوة عوديد النبي تشدد ونزع الرجاسات من كل أرض يهوذا وبنيامين ومن المدن التي أخذها من جبل أفرايم وجدد مذبح الرب الذي أمام رواق الرب.","15:9":"وجمع كل يهوذا وبنيامين والغرباء معهم من أفرايم ومنسى ومن شمعون لأنهم سقطوا إليه من إسرائيل بكثرة حين رأوا أن الرب إلهه معه.","15:10":"فاجتمعوا في أورشليم في الشهر الثالث في السنة الخامسة عشرة لملك آسا","15:11":"وذبحوا للرب في ذلك اليوم من الغنيمة التي جلبوا سبع مئة من البقر وسبعة آلاف من الضأن.","15:12":"ودخلوا في عهد أن يطلبوا الرب إله آبائهم بكل قلوبهم وكل أنفسهم.","15:13":"حتى إن كل من لا يطلب الرب إله إسرائيل يقتل من الصغير إلى الكبير من الرجال والنساء.","15:14":"وحلفوا للرب بصوت عظيم وهتاف وبأبواق وقرون.","15:15":"وفرح كل يهوذا من أجل الحلف لأنهم حلفوا بكل قلوبهم وطلبوه بكل رضاهم فوجد لهم وأراحهم الرب من كل جهة.","15:16":"حتى إن معكة أم آسا الملك خلعها من أن تكون ملكة لأنها عملت لسارية تمثالا وقطع آسا تمثالها ودقه وأحرقه في وادي قدرون.","15:17":"وأما المرتفعات فلم تنزع من إسرائيل. إلا أن قلب آسا كان كاملا كل أيامه.","15:18":"وأدخل أقداس أبيه وأقداسه إلى بيت الله من الفضة والذهب والآنية.","15:19":"ولم تكن حرب إلى السنة الخامسة والثلاثين لملك آسا.","16:1":"في السنة السادسة والثلاثين لملك آسا صعد بعشا ملك إسرائيل على يهوذا وبنى الرامة لكيلا يدع أحدا يخرج أو يدخل إلى آسا ملك يهوذا.","16:2":"وأخرج آسا فضة وذهبا من خزائن بيت الرب وبيت الملك وأرسل إلى بنهدد ملك أرام الساكن في دمشق قائلا:","16:3":"[إن بيني وبينك وبين أبي وأبيك عهدا. هوذا قد أرسلت لك فضة وذهبا فتعال انقض عهدك مع بعشا ملك إسرائيل فيصعد عني].","16:4":"فسمع بنهدد للملك آسا وأرسل رؤساء الجيوش التي له على مدن إسرائيل فضربوا عيون ودان وآبل المياه وجميع مخازن مدن نفتالي.","16:5":"فلما سمع بعشا كف عن بناء الرامة وترك عمله.","16:6":"فأخذ آسا الملك كل يهوذا فحملوا حجارة الرامة وأخشابها التي بنى بها بعشا وبنى بها جبع والمصفاة.","16:7":"وفي ذلك الزمان جاء حناني الرائي إلى آسا ملك يهوذا وقال له: [من أجل أنك استندت على ملك أرام ولم تستند على الرب إلهك لذلك قد نجا جيش ملك أرام من يدك.","16:8":"ألم يكن الكوشيون واللوبيون جيشا كثيرا بمركبات وفرسان كثيرة جدا؟ فمن أجل أنك استندت على الرب دفعهم ليدك.","16:9":"لأن عيني الرب تجولان في كل الأرض ليتشدد مع الذين قلوبهم كاملة نحوه فقد حمقت في هذا حتى إنه من الآن تكون عليك حروب.","16:10":"فغضب آسا على الرائي ووضعه في السجن لأنه اغتاظ منه من أجل هذا وضايق آسا بعضا من الشعب في ذلك الوقت.","16:11":"وأمور آسا الأولى والأخيرة مكتوبة في سفر الملوك ليهوذا وإسرائيل.","16:12":"ومرض آسا في السنة التاسعة والثلاثين من ملكه في رجليه حتى اشتد مرضه وفي مرضه أيضا لم يطلب الرب بل الأطباء.","16:13":"ثم اضطجع آسا مع آبائه ومات في السنة الحادية والأربعين لملكه","16:14":"فدفنوه في قبوره التي حفرها لنفسه في مدينة داود وأضجعوه في سرير كان مملوا أطيابا وأصنافا عطرة حسب صناعة العطارة. وأحرقوا له حريقة عظيمة جدا.","17:1":"وملك يهوشافاط ابنه عوضا عنه وتشدد على إسرائيل.","17:2":"وجعل جيشا في جميع مدن يهوذا الحصينة وجعل وكلاء في أرض يهوذا وفي مدن أفرايم التي أخذها آسا أبوه.","17:3":"وكان الرب مع يهوشافاط لأنه سار في طرق داود أبيه الأولى ولم يطلب البعليم","17:4":"ولكنه طلب إله أبيه وسار في وصاياه لا حسب أعمال إسرائيل.","17:5":"فثبت الرب المملكة في يده وقدم كل يهوذا هدايا ليهوشافاط. وكان له غنى وكرامة بكثرة.","17:6":"وتقوى قلبه في طرق الرب ونزع أيضا المرتفعات والسواري من يهوذا.","17:7":"وفي السنة الثالثة لملكه أرسل إلى رؤسائه إلى بنحائل وعوبديا وزكريا ونثنئيل وميخايا أن يعلموا في مدن يهوذا","17:8":"ومعهم اللاويون شمعيا ونثنيا وزبديا وعسائيل وشميراموث ويهوناثان وأدونيا وطوبيا وطوب أدونيا اللاويون ومعهم أليشمع ويهورام الكاهنان.","17:9":"فعلموا في يهوذا ومعهم سفر شريعة الرب وجالوا في جميع مدن يهوذا وعلموا الشعب.","17:10":"وكانت هيبة الرب على جميع ممالك الأراضي التي حول يهوذا فلم يحاربوا يهوشافاط.","17:11":"وبعض الفلسطينيين أتوا يهوشافاط بهدايا وحمل فضة والعربان أيضا أتوه بغنم من الكباش سبعة آلاف وسبع مئة ومن التيوس سبعة آلاف وسبع مئة.","17:12":"وكان يهوشافاط يتعظم جدا وبنى في يهوذا حصونا ومدن مخازن.","17:13":"وكان له شغل كثير في مدن يهوذا ورجال حرب جبابرة بأس في أورشليم.","17:14":"وهذا عددهم حسب بيوت آبائهم من يهوذا رؤساء ألوف: عدنة الرئيس ومعه جبابرة بأس ثلاث مئة ألف.","17:15":"وبجانبه يهوناثان الرئيس ومعه مئتان وثمانون ألفا.","17:16":"وبجانبه عمسيا بن زكري المنتدب للرب ومعه مئتا ألف جبار بأس.","17:17":"ومن بنيامين ألياداع جبار بأس ومعه من المتسلحين بالقسي والأتراس مئتا ألف.","17:18":"وبجانبه يهوزاباد ومعه مئة وثمانون ألفا متجردون للحرب.","17:19":"هؤلاء خدام الملك فضلا عن الذين جعلهم الملك في المدن الحصينة في كل يهوذا.","18:1":"وكان ليهوشافاط غنى وكرامة بكثرة. وصاهر أخآب.","18:2":"ونزل بعد سنين إلى أخآب إلى السامرة فذبح أخآب غنما وبقرا بكثرة له وللشعب الذي معه وأغواه أن يصعد إلى راموت جلعاد.","18:3":"وقال أخآب ملك إسرائيل ليهوشافاط ملك يهوذا: [أتذهب معي إلى راموت جلعاد؟] فقال له: [مثلي مثلك وشعبي كشعبك ومعك في القتال].","18:4":"ثم قال يهوشافاط لملك إسرائيل: [اسأل اليوم عن كلام الرب].","18:5":"فجمع ملك إسرائيل الأنبياء أربع مئة رجل وقال لهم: [أنذهب إلى راموت جلعاد للقتال أم أمتنع؟] فقالوا: [اصعد فيدفعها الله ليد الملك].","18:6":"فقال يهوشافاط: [أليس هنا أيضا نبي للرب فنسأل منه؟]","18:7":"فقال ملك إسرائيل ليهوشافاط: [بعد رجل واحد لسؤال الرب به ولكنني أبغضه لأنه لا يتنبأ علي خيرا بل شرا كل أيامه وهو ميخا بن يملة]. فقال يهوشافاط: [لا يقل الملك هكذا].","18:8":"فدعا ملك إسرائيل خصيا وقال: [أسرع بميخا بن يملة].","18:9":"وكان ملك إسرائيل ويهوشافاط ملك يهوذا جالسين كل واحد على كرسيه لابسين ثيابهما وجالسين في ساحة عند مدخل باب السامرة وجميع الأنبياء يتنبأون أمامهما.","18:10":"وعمل صدقيا بن كنعنة لنفسه قرون حديد وقال: [هكذا قال الرب: بهذه تنطح الأراميين حتى يفنوا].","18:11":"وتنبأ جميع الأنبياء هكذا قائلين: [اصعد إلى راموت جلعاد وأفلح فيدفعها الرب ليد الملك].","18:12":"وقال الرسول الذي ذهب ليدعو ميخا: [هوذا كلام جميع الأنبياء بفم واحد خير للملك. فليكن كلامك كواحد منهم وتكلم بخير].","18:13":"فقال ميخا: [حي هو الرب إن ما يقوله إلهي فبه أتكلم].","18:14":"ولما جاء إلى الملك قال له الملك: [يا ميخا أنذهب إلى راموت جلعاد للقتال أم أمتنع؟] فقال: [اصعدوا وأفلحوا فيدفعوا ليدكم].","18:15":"فقال له الملك: [كم مرة أستحلفك أن لا تقول لي إلا الحق باسم الرب!]","18:16":"فقال: [رأيت كل إسرائيل مشتتين على الجبال كخراف لا راعي لها. فقال الرب: ليس لهؤلاء أصحاب فليرجعوا كل واحد إلى بيته بسلام].","18:17":"فقال ملك إسرائيل ليهوشافاط: [أما قلت لك إنه لا يتنبأ علي خيرا بل شرا؟]","18:18":"وقال: [فاسمع إذا كلام الرب. قد رأيت الرب جالسا على كرسيه وكل جند السماء وقوف عن يمينه وعن يساره.","18:19":"فقال الرب: [من يغوي أخآب ملك إسرائيل فيصعد ويسقط في راموت جلعاد؟ فقال هذا هكذا وقال ذاك هكذا.","18:20":"ثم خرج الروح ووقف أمام الرب وقال: [أنا أغويه. فسأله الرب: [بماذا؟]","18:21":"فقال: [أخرج وأكون روح كذب في أفواه جميع أنبيائه]. فقال: [إنك تغويه وتقتدر. فاخرج وافعل هكذا.","18:22":"والآن هوذا قد جعل الرب روح كذب في أفواه أنبيائك هؤلاء والرب تكلم عليك بشر].","18:23":"فتقدم صدقيا بن كنعنة وضرب ميخا على الفك وقال: [من أي طريق عبر روح الرب مني ليكلمك؟].","18:24":"فقال ميخا: [إنك سترى في ذلك اليوم الذي تدخل فيه من مخدع إلى مخدع لتختبئ].","18:25":"فقال ملك إسرائيل: [خذوا ميخا وردوه إلى أمون رئيس المدينة وإلى يوآش ابن الملك","18:26":"وقولوا هكذا يقول الملك: ضعوا هذا في السجن وأطعموه خبز الضيق وماء الضيق حتى أرجع بسلام].","18:27":"فقال ميخا: [إن رجعت رجوعا بسلام فلم يتكلم الرب بي]. وقال: [اسمعوا أيها الشعوب أجمعون].","18:28":"فصعد ملك إسرائيل ويهوشافاط ملك يهوذا إلى راموت جلعاد.","18:29":"وقال ملك إسرائيل ليهوشافاط: [إني أتنكر وأدخل الحرب وأما أنت فالبس ثيابك]. فتنكر ملك إسرائيل ودخلا الحرب.","18:30":"وأمر ملك أرام رؤساء المركبات التي له: [لا تحاربوا صغيرا ولا كبيرا إلا ملك إسرائيل وحده].","18:31":"فلما رأى رؤساء المركبات يهوشافاط قالوا إنه ملك إسرائيل فحاوطوه للقتال فصرخ يهوشافاط وساعده الرب وحولهم عنه.","18:32":"فلما رأى رؤساء المركبات أنه ليس ملك إسرائيل رجعوا عنه.","18:33":"وإن رجلا نزع في قوسه غير متعمد وضرب ملك إسرائيل بين أوصال الدرع فقال لمدير المركبة: [رد يدك وأخرجني من الجيش لأني قد جرحت].","18:34":"واشتد القتال في ذلك اليوم وأوقف ملك إسرائيل في المركبة مقابل أرام إلى المساء ومات عند غروب الشمس.","19:1":"ورجع يهوشافاط ملك يهوذا إلى بيته بسلام إلى أورشليم.","19:2":"وخرج للقائه ياهو بن حناني الرائي وقال للملك يهوشافاط: [أتساعد الشرير وتحب مبغضي الرب؟ فلذلك الغضب عليك من قبل الرب.","19:3":"غير أنه وجدت فيك أمور صالحة لأنك نزعت السواري من الأرض وهيأت قلبك لطلب الله].","19:4":"وأقام يهوشافاط في أورشليم ثم رجع وخرج أيضا بين الشعب من بئر سبع إلى جبل أفرايم وردهم إلى الرب إله آبائهم.","19:5":"وأقام قضاة في الأرض في كل مدن يهوذا المحصنة في كل مدينة فمدينة.","19:6":"وقال للقضاة: [انظروا ما أنتم فاعلون لأنكم لا تقضون للإنسان بل للرب وهو معكم في أمر القضاء.","19:7":"والآن لتكن هيبة الرب عليكم. احذروا وافعلوا. لأنه ليس عند الرب إلهنا ظلم ولا محاباة ولا ارتشاء].","19:8":"وكذا في أورشليم أقام يهوشافاط من اللاويين والكهنة ومن رؤوس آباء إسرائيل لقضاء الرب والدعاوي. ورجعوا إلى أورشليم.","19:9":"وأمرهم: [هكذا تفعلون بتقوى الرب بأمانة وقلب كامل.","19:10":"وفي كل دعوى تأتي إليكم من إخوتكم الساكنين في مدنهم بين دم ودم بين شريعة ووصية من جهة فرائض أو أحكام حذروهم فلا يأثموا إلى الرب فيكون غضب عليكم وعلى إخوتكم. هكذا افعلوا فلا تأثموا.","19:11":"وهوذا أمريا الكاهن الرأس عليكم في كل أمور الرب وزبديا بن يشمعئيل الرئيس على بيت يهوذا في كل أمور الملك والعرفاء اللاويون أمامكم. تشددوا وافعلوا وليكن الرب مع الصالح].","20:1":"ثم بعد ذلك أتى بنو موآب وبنو عمون ومعهم العمونيون على يهوشافاط للمحاربة.","20:2":"فجاء أناس وأخبروا يهوشافاط: [قد جاء عليك جمهور كثير من عبر البحر من أرام وها هم في حصون تامار] (هي عين جدي).","20:3":"فخاف يهوشافاط وجعل وجهه ليطلب الرب ونادى بصوم في كل يهوذا.","20:4":"واجتمع يهوذا ليسألوا الرب. جاءوا أيضا من كل مدن يهوذا ليسألوا الرب.","20:5":"فوقف يهوشافاط في جماعة يهوذا وأورشليم في بيت الرب أمام الدار الجديدة","20:6":"وقال: [يا رب إله آبائنا أما أنت هو الله في السماء وأنت المتسلط على جميع ممالك الأمم وبيدك قوة وجبروت وليس من يقف معك؟","20:7":"ألست أنت إلهنا الذي طردت سكان هذه الأرض من أمام شعبك إسرائيل وأعطيتها لنسل إبراهيم خليلك إلى الأبد","20:8":"فسكنوا فيها وبنوا لك فيها مقدسا لاسمك قائلين:","20:9":"إذا جاء علينا شر سيف قضاء أو وبأ أو جوع ووقفنا أمام هذا البيت وأمامك (لأن اسمك في هذا البيت) وصرخنا إليك من ضيقنا فإنك تسمع وتخلص؟","20:10":"والآن هوذا بنو عمون وموآب وجبل ساعير الذين لم تدع إسرائيل يدخلون إليهم حين جاءوا من أرض مصر بل مالوا عنهم ولم يهلكوهم","20:11":"فهوذا هم يكافئوننا بمجيئهم لطردنا من ملكك الذي ملكتنا إياه.","20:12":"يا إلهنا أما تقضي عليهم لأنه ليس فينا قوة أمام هذا الجمهور الكثير الآتي علينا ونحن لا نعلم ماذا نعمل ولكن نحوك أعيننا].","20:13":"وكان كل يهوذا واقفين أمام الرب مع أطفالهم ونسائهم وبنيهم.","20:14":"وإن يحزئيل بن زكريا بن بنايا بن يعيئيل بن متنيا اللاوي من بني آساف كان عليه روح الرب في وسط الجماعة","20:15":"فقال: [اصغوا يا جميع يهوذا وسكان أورشليم وأيها الملك يهوشافاط. هكذا قال الرب لكم: لا تخافوا ولا ترتاعوا بسبب هذا الجمهور الكثير لأن الحرب ليست لكم بل لله.","20:16":"غدا انزلوا عليهم. هوذا هم صاعدون في عقبة صيص فتجدوهم في أقصى الوادي أمام برية يروئيل.","20:17":"ليس عليكم أن تحاربوا في هذه. قفوا اثبتوا وانظروا خلاص الرب معكم يا يهوذا وأورشليم لا تخافوا ولا ترتاعوا. غدا اخرجوا للقائهم والرب معكم].","20:18":"فخر يهوشافاط لوجهه على الأرض وكل يهوذا وسكان أورشليم سقطوا أمام الرب سجودا للرب.","20:19":"فقام اللاويون من بني القهاتيين ومن بني القورحيين ليسبحوا الرب إله إسرائيل بصوت عظيم جدا.","20:20":"وبكروا صباحا وخرجوا إلى برية تقوع. وعند خروجهم وقف يهوشافاط وقال: [اسمعوا يا يهوذا وسكان أورشليم آمنوا بالرب إلهكم فتأمنوا. آمنوا بأنبيائه فتفلحوا].","20:21":"ولما استشار الشعب أقام مغنين للرب ومسبحين في زينة مقدسة عند خروجهم أمام المتجردين وقائلين: [احمدوا الرب لأن إلى الأبد رحمته].","20:22":"ولما ابتدأوا في الغناء والتسبيح جعل الرب أكمنة على بني عمون وموآب وجبل ساعير الآتين على يهوذا فانكسروا.","20:23":"وقام بنو عمون وموآب على سكان جبل ساعير ليحرموهم ويهلكوهم. ولما فرغوا من سكان ساعير ساعد بعضهم على إهلاك بعض.","20:24":"ولما جاء يهوذا إلى المرقب في البرية تطلعوا نحو الجمهور وإذا هم جثث ساقطة على الأرض ولم ينفلت أحد.","20:25":"فأتى يهوشافاط وشعبه لنهب أموالهم فوجدوا بينهم أموالا وجثثا وأمتعة ثمينة بكثرة فأخذوها لأنفسهم حتى لم يقدروا أن يحملوها. وكانوا ثلاثة أيام ينهبون الغنيمة لأنها كانت كثيرة.","20:26":"وفي اليوم الرابع اجتمعوا في وادي بركة لأنهم هناك باركوا الرب لذلك دعوا اسم ذلك المكان [وادي بركة] إلى اليوم.","20:27":"ثم ارتد كل رجال يهوذا وأورشليم ويهوشافاط برأسهم ليرجعوا إلى أورشليم بفرح لأن الرب فرحهم على أعدائهم.","20:28":"ودخلوا أورشليم بالرباب والعيدان والأبواق إلى بيت الرب.","20:29":"وكانت هيبة الله على كل ممالك الأراضي حين سمعوا أن الرب حارب أعداء إسرائيل.","20:30":"واستراحت مملكة يهوشافاط وأراحه إلهه من كل جهة.","20:31":"وملك يهوشافاط على يهوذا. كان ابن خمس وثلاثين سنة حين ملك وملك خمسا وعشرين سنة في أورشليم واسم أمه عزوبة بنت شلحي.","20:32":"وسار في طريق أبيه آسا ولم يحد عنها إذ عمل المستقيم في عيني الرب.","20:33":"إلا أن المرتفعات لم تنتزع بل كان الشعب لم يعدوا بعد قلوبهم لإله آبائهم.","20:34":"وبقية أمور يهوشافاط الأولى والأخيرة مكتوبة في أخبار ياهو بن حناني المذكور في سفر ملوك إسرائيل.","20:35":"ثم بعد ذلك اتحد يهوشافاط ملك يهوذا مع أخزيا ملك إسرائيل الذي أساء في عمله.","20:36":"فاتحد معه في عمل سفن تسير إلى ترشيش فعملا السفن في عصيون جابر.","20:37":"وتنبأ أليعزر بن دوداوا من مريشة على يهوشافاط قائلا: [لأنك اتحدت مع أخزيا قد اقتحم الرب أعمالك]. فتكسرت السفن ولم تستطع السير إلى ترشيش.","21:1":"واضطجع يهوشافاط مع آبائه فدفن مع آبائه في مدينة داود وملك يهورام ابنه عوضا عنه.","21:2":"وكان له إخوة بنو يهوشافاط: عزريا ويحيئيل وزكريا وعزرياهو وميخائيل وشفطيا. كل هؤلاء بنو يهوشافاط ملك إسرائيل.","21:3":"وأعطاهم أبوهم عطايا كثيرة من فضة وذهب وتحف مع مدن حصينة في يهوذا. وأما المملكة فأعطاها ليهورام لأنه البكر.","21:4":"فقام يهورام على مملكة أبيه وتشدد وقتل جميع إخوته بالسيف وأيضا بعضا من رؤساء إسرائيل.","21:5":"كان يهورام ابن اثنتين وثلاثين سنة حين ملك وملك ثماني سنين في أورشليم.","21:6":"وسار في طريق ملوك إسرائيل كما فعل بيت أخآب لأن بنت أخآب كانت له امرأة. وعمل الشر في عيني الرب.","21:7":"ولم يشإ الرب أن يبيد بيت داود لأجل العهد الذي قطعه مع داود ولأنه قال إنه يعطيه وبنيه سراجا كل الأيام.","21:8":"في أيامه عصى أدوم على يهوذا وملكوا على أنفسهم ملكا.","21:9":"وعبر يهورام مع رؤسائه وجميع المركبات معه وقام ليلا وضرب أدوم المحيط به ورؤساء المركبات.","21:10":"فعصى أدوم على يهوذا إلى هذا اليوم. حينئذ عصت لبنة في ذلك الوقت عليه لأنه ترك الرب إله آبائه.","21:11":"وهو أيضا عمل مرتفعات في جبال يهوذا وجعل سكان أورشليم يزنون وطوح يهوذا.","21:12":"وأتت إليه كتابة من إيليا النبي تقول: [هكذا قال الرب إله داود أبيك: من أجل أنك لم تسلك في طرق يهوشافاط أبيك وطرق آسا ملك يهوذا","21:13":"بل سلكت في طرق ملوك إسرائيل وجعلت يهوذا وسكان أورشليم يزنون كزنا بيت أخآب وقتلت أيضا إخوتك من بيت أبيك الذين هم أفضل منك","21:14":"هوذا يضرب الرب شعبك وبنيك ونساءك وكل مالك ضربة عظيمة.","21:15":"وإياك بأمراض كثيرة بداء أمعائك حتى تخرج أمعاؤك بسبب المرض يوما فيوما].","21:16":"وأهاج الرب على يهورام روح الفلسطينيين والعرب الذين بجانب الكوشيين","21:17":"فصعدوا إلى يهوذا وافتتحوها وسبوا كل الأموال الموجودة في بيت الملك مع بنيه ونسائه أيضا ولم يبق له ابن إلا يهوآحاز أصغر بنيه.","21:18":"وبعد هذا كله ضربه الرب في أمعائه بمرض ليس له شفاء.","21:19":"وكان من يوم إلى يوم وحسب ذهاب المدة عند نهاية سنتين أن أمعاءه خرجت بسبب مرضه فمات بأمراض رديئة ولم يعمل له شعبه حريقة كحريقة آبائه.","21:20":"كان ابن اثنتين وثلاثين سنة حين ملك وملك ثماني سنين في أورشليم وذهب غير مأسوف عليه ودفنوه في مدينة داود ولكن ليس في قبور الملوك.","22:1":"وملك سكان أورشليم أخزيا ابنه الأصغر عوضا عنه لأن جميع الأولين قتلهم الغزاة الذين جاءوا مع العرب إلى المحلة. فملك أخزيا بن يهورام ملك يهوذا.","22:2":"كان أخزيا ابن اثنتين وأربعين سنة حين ملك وملك سنة واحدة في أورشليم واسم أمه عثليا بنت عمري.","22:3":"وهو أيضا سلك في طرق بيت أخآب لأن أمه كانت تشير عليه بفعل الشر.","22:4":"فعمل الشر في عيني الرب مثل بيت أخآب لأنهم كانوا له مشيرين بعد وفاة أبيه لإبادته.","22:5":"فسلك بمشورتهم وذهب مع يورام بن أخآب ملك إسرائيل لمحاربة حزائيل ملك أرام في راموت جلعاد. وضرب الأراميون يورام","22:6":"فرجع ليبرأ في يزرعيل بسبب الضربات التي ضربوه بها في الرامة عند محاربته حزائيل ملك أرام. ونزل أخزيا بن يهورام ملك يهوذا ليزور يورام بن أخآب في يزرعيل لأنه كان مريضا.","22:7":"فمن قبل الله كان هلاك أخزيا بمجيئه إلى يورام. فإنه حين جاء خرج مع يورام إلى ياهو بن نمشي الذي مسحه الرب لقطع بيت أخآب.","22:8":"وإذ كان ياهو يقضي على بيت أخآب وجد رؤساء يهوذا وبني إخوة أخزيا الذين كانوا يخدمون أخزيا فقتلهم.","22:9":"وطلب أخزيا فأمسكوه وهو مختبئ في السامرة وأتوا به إلى ياهو وقتلوه ودفنوه لأنهم قالوا إنه ابن يهوشافاط الذي طلب الرب بكل قلبه. فلم يكن لبيت أخزيا من يقوى على المملكة.","22:10":"ولما رأت عثليا أم أخزيا أن ابنها قد مات قامت وأبادت جميع النسل الملكي من بيت يهوذا.","22:11":"أما يهوشبعة بنت الملك فأخذت يهوآش بن أخزيا وسرقته من وسط بني الملك الذين قتلوا وجعلته هو ومرضعته في مخدع السرير وخبأته يهوشبعة بنت الملك يهورام امرأة يهوياداع الكاهن. (لأنها كانت أخت أخزيا) من وجه عثليا فلم تقتله.","22:12":"وكان معهم في بيت الله مختبئا ست سنين وعثليا مالكة على الأرض.","23:1":"وفي السنة السابعة تشدد يهوياداع وأخذ معه في العهد رؤساء المئات: عزريا بن يروحام وإسماعيل بن يهوحانان وعزريا بن عوبيد ومعسيا بن عدايا وأليشافاط بن زكري","23:2":"وجالوا في يهوذا وجمعوا اللاويين من جميع مدن يهوذا ورؤوس آباء إسرائيل وجاءوا إلى أورشليم.","23:3":"وقطع كل المجمع عهدا في بيت الله مع الملك. وقال لهم: [هوذا ابن الملك يملك كما تكلم الرب عن بني داود.","23:4":"هذا هو الأمر الذي تعملونه. الثلث منكم الذين يدخلون في السبت من الكهنة واللاويين يكونون بوابين للأبواب","23:5":"والثلث في بيت الملك والثلث في باب الأساس وجميع الشعب في ديار بيت الرب.","23:6":"ولا يدخل بيت الرب إلا الكهنة والذين يخدمون من اللاويين فهم يدخلون لأنهم مقدسون وكل الشعب يحرسون حراسة الرب.","23:7":"ويحيط اللاويون بالملك مستديرين كل واحد سلاحه بيده. والذي يدخل البيت يقتل. وكونوا مع الملك في دخوله وفي خروجه].","23:8":"فعمل اللاويون وكل يهوذا حسب كل ما أمر به يهوياداع الكاهن. وأخذوا كل واحد رجاله الداخلين في السبت مع الخارجين في السبت لأن يهوياداع الكاهن لم يصرف الفرق.","23:9":"وأعطى يهوياداع الكاهن رؤساء المئات الحراب والمجان والأتراس التي للملك داود التي في بيت الله.","23:10":"وأوقف جميع الشعب وكل واحد سلاحه بيده من جانب البيت الأيمن إلى جانب البيت الأيسر حول المذبح والبيت حول الملك مستديرين.","23:11":"ثم أخرجوا ابن الملك ووضعوا عليه التاج وأعطوه الشهادة وملكوه. ومسحه يهوياداع وبنوه وقالوا: [ليحي الملك!].","23:12":"ولما سمعت عثليا صوت الشعب يركضون ويمدحون الملك دخلت إلى الشعب في بيت الرب.","23:13":"ونظرت وإذا الملك واقف على منبره في المدخل والرؤساء والأبواق عند الملك وكل شعب الأرض يفرحون وينفخون بالأبواق والمغنون بآلات الغناء والمعلمون التسبيح. فشقت عثليا ثيابها وقالت: [خيانة! خيانة!]","23:14":"فأخرج يهوياداع الكاهن رؤساء المئات الموكلين على الجيش وقال لهم: [أخرجوها إلى خارج الصفوف والذي يتبعها يقتل بالسيف]. لأن الكاهن قال: [لا تقتلوها في بيت الرب].","23:15":"فألقوا عليها الأيادي. ولما أتت إلى مدخل باب الخيل إلى بيت الملك قتلوها هناك.","23:16":"فقطع يهوياداع عهدا بينه وبين كل الشعب وبين الملك أن يكونوا شعبا للرب.","23:17":"ودخل جميع الشعب إلى بيت البعل وهدموه وكسروا مذابحه وتماثيله وقتلوا متان كاهن البعل أمام المذبح.","23:18":"وجعل يهوياداع حراسا على بيت الرب عن يد الكهنة اللاويين الذين قسمهم داود على بيت الرب لإصعاد محرقات الرب كما هو مكتوب في شريعة موسى بالفرح والغناء حسب أمر داود.","23:19":"وأوقف البوابين على أبواب بيت الرب لئلا يدخل نجس في أمر ما.","23:20":"وأخذ رؤساء المئات والعظماء والمتسلطين على الشعب وكل شعب الأرض وأنزل الملك من بيت الرب ودخلوا من وسط الباب الأعلى إلى بيت الملك وأجلسوا الملك على كرسي المملكة.","23:21":"ففرح كل شعب الأرض واستراحت المدينة وقتلوا عثليا بالسيف.","24:1":"كان يهوآش ابن سبع سنين حين ملك وملك أربعين سنة في أورشليم واسم أمه ظبية من بئر سبع.","24:2":"وعمل يهوآش المستقيم في عيني الرب كل أيام يهوياداع الكاهن.","24:3":"واتخذ يهوياداع له امرأتين فولد بنين وبنات.","24:4":"وحدث بعد ذلك أنه كان في قلب يهوآش أن يجدد بيت الرب.","24:5":"فجمع الكهنة واللاويين وقال لهم: [اخرجوا إلى مدن يهوذا واجمعوا من جميع إسرائيل فضة لأجل ترميم بيت إلهكم من سنة إلى سنة وبادروا أنتم إلى هذا الأمر]. فلم يبادر اللاويون.","24:6":"فدعا الملك يهوياداع الرئيس وسأله: [لماذا لم تطلب من اللاويين أن يأتوا من يهوذا وأورشليم بجزية موسى عبد الرب وجماعة إسرائيل لخيمة الشهادة؟","24:7":"لأن بني عثليا الخبيثة قد هدموا بيت الله وصيروا كل أقداس بيت الرب للبعليم].","24:8":"وأمر الملك فعملوا صندوقا وجعلوه في باب بيت الرب خارجا","24:9":"ونادوا في يهوذا وأورشليم بأن يأتوا إلى الرب بجزية موسى عبد الرب المفروضة على إسرائيل في البرية.","24:10":"ففرح كل الرؤساء وكل الشعب وأدخلوا وألقوا في الصندوق حتى امتلأ.","24:11":"وحينما كان يؤتى بالصندوق إلى وكالة الملك بيد اللاويين عندما يرون أن الفضة قد كثرت كان يأتي كاتب الملك ووكيل الكاهن الرئيس ويفرغان الصندوق ثم يحملانه ويردانه إلى مكانه. هكذا كانوا يفعلون يوما فيوما حتى جمعوا فضة بكثرة.","24:12":"ودفعها الملك ويهوياداع لعاملي شغل خدمة بيت الرب وكانوا يستأجرون نحاتين ونجارين لتجديد بيت الرب وللعاملين في الحديد والنحاس أيضا لترميم بيت الرب.","24:13":"فعمل عاملو الشغل ونجح العمل بأيديهم وأقاموا بيت الله على رسمه وثبتوه.","24:14":"ولما أكملوا أتوا إلى ما بين يدي الملك ويهوياداع ببقية الفضة وعملوها آنية لبيت الرب آنية خدمة وإصعاد وصحونا وآنية ذهب وفضة. وكانوا يصعدون محرقات في بيت الرب دائما كل أيام يهوياداع.","24:15":"وشاخ يهوياداع وشبع من الأيام ومات. كان ابن مئة وثلاثين سنة عند وفاته.","24:16":"فدفنوه في مدينة داود مع الملوك لأنه عمل خيرا في إسرائيل ومع الله وبيته.","24:17":"وبعد موت يهوياداع جاء رؤساء يهوذا وسجدوا للملك. حينئذ سمع الملك لهم.","24:18":"وتركوا بيت الرب إله آبائهم وعبدوا السواري والأصنام فكان غضب على يهوذا وأورشليم لأجل إثمهم هذا.","24:19":"وأرسل إليهم أنبياء لإرجاعهم إلى الرب وأشهدوا عليهم فلم يصغوا.","24:20":"ولبس روح الله زكريا بن يهوياداع الكاهن فوقف فوق الشعب وقال لهم: [هكذا يقول الله: لماذا تتعدون وصايا الرب فلا تفلحون؟ لأنكم تركتم الرب قد ترككم].","24:21":"ففتنوا عليه ورجموه بحجارة بأمر الملك في دار بيت الرب.","24:22":"ولم يذكر يهوآش الملك المعروف الذي عمله يهوياداع أبوه معه بل قتل ابنه. وعند موته قال: [الرب ينظر ويطالب].","24:23":"وفي مدار السنة صعد عليه جيش أرام وأتوا إلى يهوذا وأورشليم وأهلكوا كل رؤساء الشعب من الشعب وجميع غنيمتهم أرسلوها إلى ملك دمشق.","24:24":"لأن جيش أرام جاء بشرذمة قليلة ودفع الرب ليدهم جيشا كثيرا جدا لأنهم تركوا الرب إله آبائهم. فأجروا قضاء على يهوآش.","24:25":"وعند ذهابهم عنه - لأنهم تركوه بأمراض كثيرة - فتن عليه عبيده من أجل دماء بني يهوياداع الكاهن وقتلوه على سريره فمات. فدفنوه في مدينة داود ولم يدفنوه في قبور الملوك.","24:26":"وهذان هما الفاتنان عليه: زاباد بن شمعة العمونية ويهوزاباد بن شمريت الموآبية.","24:27":"وأما بنوه وكثرة ما حمل عليه ومرمة بيت الله ممكتوبة في مدرس سفر الملوك. وملك أمصيا ابنه عوضا عنه.","25:1":"ملك أمصيا وهو ابن خمس وعشرين سنة وملك تسعا وعشرين سنة في أورشليم واسم أمه يهوعدان من أورشليم.","25:2":"وعمل المستقيم في عيني الرب ولكن ليس بقلب كامل.","25:3":"ولما تثبتت المملكة عليه قتل عبيده الذين قتلوا الملك أباه.","25:4":"وأما بنوهم فلم يقتلهم بل كما هو مكتوب في الشريعة في سفر موسى حيث أمر الرب: [لا تموت الآباء لأجل البنين ولا البنون يموتون لأجل الآباء بل كل واحد يموت لأجل خطيته].","25:5":"وجمع أمصيا يهوذا وأقامهم حسب بيوت الآباء رؤساء ألوف ورؤساء مئات في كل يهوذا وبنيامين وأحصاهم من ابن عشرين سنة فما فوق فوجدهم ثلاث مئة ألف مختار خارج للحرب حامل رمح وترس.","25:6":"واستأجر من إسرائيل مئة ألف جبار بأس بمئة وزنة من الفضة.","25:7":"وجاء إليه رجل الله قائلا: [أيها الملك لا يأتي معك جيش إسرائيل لأن الرب ليس مع إسرائيل مع كل بني أفرايم.","25:8":"وإن ذهبت أنت فاعمل وتشدد للقتال لأن الله يسقطك أمام العدو لأن عند الله قوة للمساعدة وللإسقاط].","25:9":"فقال أمصيا لرجل الله: [فماذا يعمل لأجل المئة الوزنة التي أعطيتها لغزاة إسرائيل؟] فقال رجل الله: [إن الرب قادر أن يعطيك أكثر منها].","25:10":"فأفرز أمصيا الغزاة الذين جاءوا إليه من أفرايم لينطلقوا إلى مكانهم فحمي غضبهم جدا على يهوذا ورجعوا إلى مكانهم بحمو الغضب.","25:11":"وأما أمصيا فتشدد واقتاد شعبه وذهب إلى وادي الملح وضرب من بني ساعير عشرة آلاف","25:12":"وعشرة آلاف أحياء سباهم بنو يهوذا وأتوا بهم إلى رأس سالع وطرحوهم عن رأس سالع فتكسروا أجمعون.","25:13":"وأما الغزاة الذين أرجعهم أمصيا عن الذهاب معه إلى القتال فاقتحموا مدن يهوذا من السامرة إلى بيت حورون وضربوا منهم ثلاثة آلاف ونهبوا نهبا كثيرا.","25:14":"ثم بعد مجيء أمصيا من ضرب الأدوميين أتى بآلهة بني ساعير وأقامهم له آلهة وسجد أمامهم وأوقد لهم.","25:15":"فحمي غضب الرب على أمصيا وأرسل إليه نبيا فقال له: [لماذا طلبت آلهة الشعب الذين لم ينقذوا شعبهم من يدك؟]","25:16":"وفيما هو يكلمه قال له: [هل جعلوك مشيرا للملك؟ كف! لماذا يقتلونك؟] فكف النبي وقال: [قد علمت أن الله قد قضى بهلاكك لأنك عملت هذا ولم تسمع لمشورتي].","25:17":"فاستشار أمصيا ملك يهوذا وأرسل إلى يوآش بن يهوآحاز بن ياهو ملك إسرائيل قائلا: [هلم نتراء مواجهة].","25:18":"فأرسل يوآش ملك إسرائيل إلى أمصيا ملك يهوذا قائلا: [العوسج الذي في لبنان أرسل إلى الأرز الذي في لبنان يقول: [أعط ابنتك لابني امرأة. فعبر حيوان بري كان في لبنان وداس العوسج.","25:19":"تقول: هئنذا قد ضربت أدوم. فرفعك قلبك للتمجد! فالآن أقم في بيتك. لماذا تهجم على الشر فتسقط أنت ويهوذا معك؟].","25:20":"فلم يسمع أمصيا لأنه كان من قبل الله أن يسلمهم لأنهم طلبوا آلهة أدوم.","25:21":"وصعد يوآش ملك إسرائيل فتراءيا مواجهة هو وأمصيا ملك يهوذا في بيت شمس التي ليهوذا.","25:22":"فانهزم يهوذا أمام إسرائيل وهربوا كل واحد إلى خيمته.","25:23":"وأما أمصيا ملك يهوذا فأمسكه يوآش ملك إسرائيل في بيت شمس وجاء به إلى أورشليم وهدم سور أورشليم من باب أفرايم إلى باب الزاوية أربع مئة ذراع.","25:24":"وأخذ كل الذهب والفضة وكل الآنية الموجودة في بيت الله مع عوبيد أدوم وخزائن بيت الملك والرهناء ورجع إلى السامرة.","25:25":"وعاش أمصيا بن يهوآش ملك يهوذا بعد موت يوآش بن يهوآحاز ملك إسرائيل خمس عشرة سنة.","25:26":"وبقية أمور أمصيا الأولى والأخيرة مكتوبة في سفر ملوك يهوذا وإسرائيل.","25:27":"ومن حين حاد أمصيا من وراء الرب فتنوا عليه في أورشليم فهرب إلى لخيش فأرسلوا وراءه إلى لخيش وقتلوه هناك","25:28":"وحملوه على الخيل ودفنوه مع آبائه في مدينة يهوذا.","26:1":"وأخذ كل شعب يهوذا عزيا وهو ابن ست عشرة سنة وملكوه عوضا عن أبيه أمصيا.","26:2":"هو بنى أيلة وردها ليهوذا بعد اضطجاع الملك مع آبائه.","26:3":"كان عزيا ابن ست عشرة سنة حين ملك وملك اثنتين وخمسين سنة في أورشليم. واسم أمه يكليا من أورشليم.","26:4":"وعمل المستقيم في عيني الرب حسب كل ما عمل أمصيا أبوه.","26:5":"وكان يطلب الله في أيام زكريا الفاهم بمناظر الله. وفي أيام طلبه الرب أنجحه الله.","26:6":"وخرج وحارب الفلسطينيين وهدم سور جت وسور يبنة وسور أشدود وبنى مدنا في أرض أشدود والفلسطينيين.","26:7":"وساعده الله على الفلسطينيين وعلى العرب الساكنين في جور بعل والمعونيين.","26:8":"وأعطى العمونيون عزيا هدايا وامتد اسمه إلى مدخل مصر لأنه تشدد جدا.","26:9":"وبنى عزيا أبراجا في أورشليم عند باب الزاوية وعند باب الوادي وعند الزاوية وحصنها.","26:10":"وبنى أبراجا في البرية وحفر آبارا كثيرة لأنه كان له ماشية كثيرة في الساحل والسهل وفلاحون وكرامون في الجبال وفي الكرمل لأنه كان يحب الفلاحة.","26:11":"وكان لعزيا جيش من المقاتلين يخرجون للحرب أحزابا حسب عدد إحصائهم عن يد يعيئيل الكاتب ومعسيا العريف تحت يد حننيا واحد من رؤساء الملك.","26:12":"كل عدد رؤوس الآباء من جبابرة البأس ألفان وست مئة.","26:13":"وتحت يدهم جيش جنود ثلاث مئة ألف وسبعة آلاف وخمس مئة من المقاتلين بقوة شديدة لمساعدة الملك على العدو.","26:14":"وهيأ لهم عزيا لكل الجيش أتراسا ورماحا وخوذا ودروعا وقسيا وحجارة مقاليع.","26:15":"وعمل في أورشليم منجنيقات اختراع مخترعين لتكون على الأبراج وعلى الزوايا لترمى بها السهام والحجارة العظيمة. وامتد اسمه إلى بعيد إذ عجبت مساعدته حتى تشدد.","26:16":"ولما تشدد ارتفع قلبه إلى الهلاك وخان الرب إلهه ودخل هيكل الرب ليوقد على مذبح البخور.","26:17":"ودخل وراءه عزريا الكاهن ومعه ثمانون من كهنة الرب بني البأس.","26:18":"وقاوموا عزيا الملك وقالوا له: [ليس لك يا عزيا أن توقد للرب بل للكهنة بني هارون المقدسين للإيقاد. اخرج من المقدس لأنك خنت وليس لك من كرامة من عند الرب الإله].","26:19":"فحنق عزيا. وكان في يده مجمرة للإيقاد. وعند حنقه على الكهنة خرج برص في جبهته أمام الكهنة في بيت الرب بجانب مذبح البخور.","26:20":"فالتفت نحوه عزرياهو الكاهن الرأس وكل الكهنة وإذا هو أبرص في جبهته فطردوه من هناك حتى إنه هو نفسه بادر إلى الخروج لأن الرب ضربه.","26:21":"وكان عزيا الملك أبرص إلى يوم وفاته وأقام في بيت المرض أبرص لأنه قطع من بيت الرب وكان يوثام ابنه على بيت الملك يحكم على شعب الأرض.","26:22":"وبقية أمور عزيا الأولى والأخيرة كتبها إشعياء بن آموص النبي.","26:23":"ثم اضطجع عزيا مع آبائه ودفنوه مع آبائه في حقل المقبرة التي للملوك لأنهم قالوا إنه أبرص. وملك يوثام ابنه عوضا عنه.","27:1":"كان يوثام ابن خمس وعشرين سنة حين ملك وملك ست عشرة سنة في أورشليم واسم أمه يروشة بنت صادوق.","27:2":"وعمل المستقيم في عيني الرب حسب كل ما عمل عزيا أبوه (إلا أنه لم يدخل هيكل الرب). وكان الشعب يفسدون بعد.","27:3":"هو بنى الباب الأعلى لبيت الرب وبنى كثيرا على سور الأكمة.","27:4":"وبنى مدنا في جبل يهوذا وبنى في الغابات قلعا وأبراجا.","27:5":"وهو حارب ملك بني عمون وقوي عليهم فأعطاه بنو عمون في تلك السنة مئة وزنة من الفضة وعشرة آلاف كر قمح وعشرة آلاف من الشعير. هذا ما أداه له بنو عمون وكذلك في السنة الثانية والثالثة.","27:6":"وتشدد يوثام لأنه هيأ طرقه أمام الرب إلهه.","27:7":"وبقية أمور يوثام وكل حروبه وطرقه مكتوبة في سفر ملوك إسرائيل ويهوذا.","27:8":"كان ابن خمس وعشرين سنة حين ملك وملك ست عشرة سنة في أورشليم.","27:9":"ثم اضطجع يوثام مع آبائه فدفنوه في مدينة داود وملك آحاز ابنه عوضا عنه.","28:1":"كان آحاز ابن عشرين سنة حين ملك وملك ست عشرة سنة في أورشليم ولم يفعل المستقيم في عيني الرب كداود أبيه","28:2":"بل سار في طرق ملوك إسرائيل وعمل أيضا تماثيل مسبوكة للبعليم.","28:3":"وهو أوقد في وادي ابن هنوم وأحرق بنيه بالنار حسب رجاسات الأمم الذين طردهم الرب من أمام بني إسرائيل.","28:4":"وذبح وأوقد على المرتفعات وعلى التلال وتحت كل شجرة خضراء.","28:5":"فدفعه الرب إلهه ليد ملك أرام فضربوه وسبوا منه سبيا عظيما وأتوا بهم إلى دمشق. ودفع أيضا ليد ملك إسرائيل فضربه ضربة عظيمة.","28:6":"وقتل فقح بن رمليا في يهوذا مئة وعشرين ألفا في يوم واحد - الجميع بنو بأس - لأنهم تركوا الرب إله آبائهم.","28:7":"وقتل زكري جبار أفرايم معسيا ابن الملك وعزريقام رئيس البيت وألقانة ثاني الملك.","28:8":"وسبى بنو إسرائيل من إخوتهم مئتي ألف من النساء والبنين والبنات ونهبوا أيضا منهم غنيمة وافرة وأتوا بالغنيمة إلى السامرة.","28:9":"وكان هناك نبي للرب اسمه عوديد فخرج للقاء الجيش الآتي إلى السامرة وقال لهم: [هوذا من أجل غضب الرب إله آبائكم على يهوذا قد دفعهم ليدكم وقد قتلتموهم بغضب بلغ السماء.","28:10":"والآن أنتم عازمون على إخضاع بني يهوذا وأورشليم عبيدا وإماء لكم. أما عندكم أنتم آثام للرب إلهكم؟","28:11":"والآن اسمعوا لي وردوا السبي الذي سبيتموه من إخوتكم لأن حمو غضب الرب عليكم].","28:12":"ثم قام رجال من رؤوس بني أفرايم: عزريا بن يهوحانان وبرخيا بن مشليموت ويحزقيا بن شلوم وعماسا بن حدلاي على المقبلين من الجيش","28:13":"وقالوا لهم: [لا تدخلون بالسبي إلى هنا لأن علينا إثما للرب وأنتم عازمون أن تزيدوا على خطايانا وعلى إثمنا لأن لنا إثما كثيرا وعلى إسرائيل حمو غضب].","28:14":"فترك المتجردون السبي والنهب أمام الرؤساء وكل الجماعة.","28:15":"وقام الرجال المعينة أسماؤهم وأخذوا المسبيين وألبسوا كل عراتهم من الغنيمة وكسوهم وحذوهم وأطعموهم وأسقوهم ودهنوهم وحملوا على حمير جميع المعيين منهم وأتوا بهم إلى أريحا مدينة النخل إلى إخوتهم. ثم رجعوا إلى السامرة.","28:16":"في ذلك الوقت أرسل الملك آحاز إلى ملوك أشور ليساعدوه.","28:17":"فإن الأدوميين أتوا أيضا وضربوا يهوذا وسبوا سبيا.","28:18":"واقتحم الفلسطينيون مدن السواحل وجنوبي يهوذا وأخذوا بيت شمس وأيلون وجديروت وسوكو وقراها وتمنة وقراها وحمزو وقراها وسكنوا هناك.","28:19":"لأن الرب ذلل يهوذا بسبب آحاز ملك إسرائيل لأنه أجمح يهوذا وخان الرب خيانة.","28:20":"فجاء عليه تغلث فلاسر ملك أشور وضايقه ولم يشدده.","28:21":"لأن آحاز أخذ قسما من بيت الرب ومن بيت الملك ومن الرؤساء وأعطاه لملك أشور ولكنه لم يساعده.","28:22":"وفي ضيقه زاد خيانة للرب (الملك آحاز هذا)","28:23":"وذبح لآلهة دمشق الذين ضاربوه وقال: [لأن آلهة ملوك أرام تساعدهم أنا أذبح لهم فيساعدونني]. وأما هم فكانوا سبب سقوط له ولكل إسرائيل.","28:24":"وجمع آحاز آنية بيت الله وقطعها وأغلق أبواب بيت الرب وعمل لنفسه مذابح في كل زاوية في أورشليم.","28:25":"وفي كل مدينة فمدينة من يهوذا عمل مرتفعات للإيقاد لآلهة أخرى وأسخط الرب إله آبائه.","28:26":"وبقية أموره وكل طرقه الأولى والأخيرة مكتوبة في سفر ملوك يهوذا وإسرائيل.","28:27":"ثم اضطجع آحاز مع آبائه فدفنوه في المدينة في أورشليم لأنهم لم يأتوا به إلى قبور ملوك إسرائيل. وملك حزقيا ابنه عوضا عنه.","29:1":"ملك حزقيا وهو ابن خمس وعشرين سنة وملك تسعا وعشرين سنة في أورشليم واسم أمه أبية بنت زكريا.","29:2":"وعمل المستقيم في عيني الرب حسب كل ما عمل داود أبوه.","29:3":"هو في السنة الأولى من ملكه في الشهر الأول فتح أبواب بيت الرب ورممها.","29:4":"وأدخل الكهنة واللاويين وجمعهم إلى الساحة الشرقية","29:5":"وقال لهم: [اسمعوا لي أيها اللاويون تقدسوا الآن وقدسوا بيت الرب إله آبائكم وأخرجوا النجاسة من القدس","29:6":"لأن آباءنا خانوا وعملوا الشر في عيني الرب إلهنا وتركوه وحولوا وجوههم عن مسكن الرب وأعطوا قفا","29:7":"وأغلقوا أيضا أبواب الرواق وأطفأوا السرج ولم يوقدوا بخورا ولم يصعدوا محرقة في القدس لإله إسرائيل.","29:8":"فكان غضب الرب على يهوذا وأورشليم وأسلمهم للقلق والدهش والصفير كما أنتم راؤون بأعينكم.","29:9":"وهوذا قد سقط آباؤنا بالسيف وبنونا وبناتنا ونساؤنا في السبي لأجل هذا.","29:10":"فالآن في قلبي أن أقطع عهدا مع الرب إله إسرائيل فيرد عنا حمو غضبه.","29:11":"يا بني لا تضلوا الآن لأن الرب اختاركم لتقفوا أمامه وتخدموه وتكونوا خادمين وموقدين له].","29:12":"فقام اللاويون محث بن عماساي ويوئيل بن عزريا من بني القهاتيين ومن بني مراري قيس بن عبدي وعزريا بن يهللئيل ومن الجرشونيين يوآخ بن زمة وعيدن بن يوآخ","29:13":"ومن بني أليصافان شمري ويعيئيل ومن بني آساف زكريا ومتنيا","29:14":"ومن بني هيمان يحيئيل وشمعي ومن بني يدوثون شمعيا وعزيئيل.","29:15":"وجمعوا إخوتهم وتقدسوا وأتوا حسب أمر الملك بكلام الرب ليطهروا بيت الرب.","29:16":"ودخل الكهنة إلى داخل بيت الرب ليطهروه وأخرجوا كل النجاسة التي وجدوها في هيكل الرب إلى دار بيت الرب وتناولها اللاويون ليخرجوها إلى الخارج إلى وادي قدرون.","29:17":"وشرعوا في التقديس في أول الشهر الأول. وفي اليوم الثامن من الشهر انتهوا إلى رواق الرب وقدسوا بيت الرب في ثمانية أيام وفي اليوم السادس عشر من الشهر الأول انتهوا.","29:18":"ودخلوا إلى داخل إلى حزقيا الملك وقالوا: [قد طهرنا كل بيت الرب ومذبح المحرقة وكل آنيته ومائدة خبز الوجوه وكل آنيتها.","29:19":"وجميع الآنية التي طرحها الملك آحاز في ملكه بخيانته قد هيأناها وقدسناها وها هي أمام مذبح الرب].","29:20":"وبكر حزقيا الملك وجمع رؤساء المدينة وصعد إلى بيت الرب.","29:21":"فأتوا بسبعة ثيران وسبعة كباش وسبعة خرفان وسبعة تيوس معزى ذبيحة خطية عن المملكة وعن المقدس وعن يهوذا. وقال لبني هارون الكهنة أن يصعدوها على مذبح الرب.","29:22":"فذبحوا الثيران وتناول الكهنة الدم ورشوه على المذبح ثم ذبحوا الكباش ورشوا الدم على المذبح ثم ذبحوا الخرفان ورشوا الدم على المذبح.","29:23":"ثم تقدموا بتيوس ذبيحة الخطية أمام الملك والجماعة ووضعوا أيديهم عليها","29:24":"وذبحها الكهنة وكفروا بدمها على المذبح تكفيرا عن جميع إسرائيل لأن الملك قال إن المحرقة وذبيحة الخطية هما عن كل إسرائيل.","29:25":"وأوقف اللاويين في بيت الرب بصنوج ورباب وعيدان حسب أمر داود وجاد رائي الملك وناثان النبي لأن من قبل الرب الوصية عن يد أنبيائه.","29:26":"فوقف اللاويون بآلات داود والكهنة بالأبواق.","29:27":"وأمر حزقيا بإصعاد المحرقة على المذبح. وعند ابتداء المحرقة ابتدأ نشيد الرب والأبواق بواسطة آلات داود ملك إسرائيل.","29:28":"وكان كل الجماعة يسجدون والمغنون يغنون والمبوقون يبوقون. الجميع إلى أن انتهت المحرقة.","29:29":"وعند انتهاء المحرقة خر الملك وكل الموجودين معه وسجدوا.","29:30":"وقال حزقيا الملك والرؤساء للاويين أن يسبحوا الرب بكلام داود وآساف الرائي فسبحوا بابتهاج وخروا وسجدوا.","29:31":"ثم قال حزقيا: [الآن ملأتم أيديكم للرب. تقدموا وأتوا بذبائح وقرابين شكر لبيت الرب]. فأتت الجماعة بذبائح وقرابين شكر وكل سموح القلب أتى بمحرقات.","29:32":"وكان عدد المحرقات التي أتى بها الجماعة سبعين ثورا ومئة كبش ومئتي خروف. كل هذه محرقة للرب.","29:33":"والأقداس ست مئة من البقر وثلاثة آلاف من الضأن.","29:34":"إلا إن الكهنة كانوا قليلين فلم يقدروا أن يسلخوا كل المحرقات فساعدهم إخوتهم اللاويون حتى كمل العمل وحتى تقدس الكهنة. لأن اللاويين كانوا أكثر استقامة قلب من الكهنة في التقدس.","29:35":"وأيضا كانت المحرقات كثيرة بشحم ذبائح السلامة وسكائب المحرقات. فاستقامت خدمة بيت الرب.","29:36":"وفرح حزقيا وكل الشعب من أجل أن الله أعد الشعب لأن الأمر كان بغتة.","30:1":"وأرسل حزقيا إلى جميع إسرائيل ويهوذا وكتب أيضا رسائل إلى أفرايم ومنسى أن يأتوا إلى بيت الرب في أورشليم ليعملوا فصحا للرب إله إسرائيل.","30:2":"فتشاور الملك ورؤساؤه وكل الجماعة في أورشليم أن يعملوا الفصح في الشهر الثاني","30:3":"لأنهم لم يقدروا أن يعملوه في ذلك الوقت لأن الكهنة لم يتقدسوا بالكفاية والشعب لم يجتمعوا إلى أورشليم.","30:4":"فحسن الأمر في عيني الملك وعيون كل الجماعة.","30:5":"فاعتمدوا على إطلاق النداء في جميع إسرائيل من بئر سبع إلى دان أن يأتوا لعمل الفصح للرب إله إسرائيل في أورشليم لأنهم لم يعملوه كما هو مكتوب منذ زمان كثير.","30:6":"فذهب السعاة بالرسائل من يد الملك ورؤسائه في جميع إسرائيل ويهوذا وحسب وصية الملك كانوا يقولون: [يا بني إسرائيل ارجعوا إلى الرب إله إبراهيم وإسحاق وإسرائيل فيرجع إلى الناجين الباقين لكم من يد ملوك أشور.","30:7":"ولا تكونوا كآبائكم وكإخوتكم الذين خانوا الرب إله آبائهم فجعلهم دهشة كما أنتم ترون.","30:8":"الآن لا تصلبوا رقابكم كآبائكم بل اخضعوا للرب وادخلوا مقدسه الذي قدسه إلى الأبد واعبدوا الرب إلهكم فيرتد عنكم حمو غضبه.","30:9":"لأنه برجوعكم إلى الرب يجد إخوتكم وبنوكم رحمة أمام الذين يسبونهم فيرجعون إلى هذه الأرض لأن الرب إلهكم حنان ورحيم ولا يحول وجهه عنكم إذا رجعتم إليه].","30:10":"فكان السعاة يعبرون من مدينة إلى مدينة في أرض أفرايم ومنسى حتى زبولون فكانوا يضحكون عليهم ويهزأون بهم.","30:11":"إلا إن قوما من أشير ومنسى وزبولون تواضعوا وأتوا إلى أورشليم.","30:12":"وكانت يد الله في يهوذا أيضا فأعطاهم قلبا واحدا ليعملوا بأمر الملك والرؤساء حسب قول الرب.","30:13":"فاجتمع إلى أورشليم شعب كثير لعمل عيد الفطير في الشهر الثاني جماعة كثيرة جدا.","30:14":"وقاموا وأزالوا المذابح التي في أورشليم وأزالوا كل مذابح التبخير وطرحوها إلى وادي قدرون.","30:15":"وذبحوا الفصح في الرابع عشر من الشهر الثاني. والكهنة واللاويون خجلوا وتقدسوا وأدخلوا المحرقات إلى بيت الرب","30:16":"وأقاموا على مقامهم حسب حكمهم كناموس موسى رجل الله. كان الكهنة يرشون الدم من يد اللاويين.","30:17":"لأنه كان كثيرون في الجماعة لم يتقدسوا فكان اللاويون على ذبح الفصح عن كل من ليس بطاهر لتقديسهم للرب.","30:18":"لأن كثيرين من الشعب كثيرين من أفرايم ومنسى ويساكر وزبولون لم يتطهروا بل أكلوا الفصح ليس كما هو مكتوب. إلا إن حزقيا صلى عنهم قائلا: [الرب الصالح يكفر عن","30:19":"كل من هيأ قلبه لطلب الله الرب إله آبائه وليس كطهارة القدس].","30:20":"فسمع الرب لحزقيا وشفى الشعب.","30:21":"وعمل بنو إسرائيل الموجودون في أورشليم عيد الفطير سبعة أيام بفرح عظيم وكان اللاويون والكهنة يسبحون الرب يوما فيوما بآلات حمد للرب.","30:22":"وطيب حزقيا قلوب جميع اللاويين الفطنين فطنة صالحة للرب وأكلوا الموسم سبعة أيام يذبحون ذبائح سلامة ويحمدون الرب إله آبائهم.","30:23":"وتشاور كل الجماعة أن يعملوا سبعة أيام أخرى فعملوا سبعة أيام بفرح.","30:24":"لأن حزقيا ملك يهوذا قدم للجماعة ألف ثور وسبعة آلاف من الضأن والرؤساء قدموا للجماعة ألف ثور وعشرة آلاف من الضأن وتقدس كثيرون من الكهنة.","30:25":"وفرح كل جماعة يهوذا والكهنة واللاويون وكل الجماعة الآتين من إسرائيل والغرباء الآتون من أرض إسرائيل والساكنون في يهوذا.","30:26":"وكان فرح عظيم في أورشليم لأنه من أيام سليمان بن داود ملك إسرائيل لم يكن كهذا في أورشليم.","30:27":"وقام الكهنة اللاويون وباركوا الشعب فسمع صوتهم ودخلت صلاتهم إلى مسكن قدسه إلى السماء.","31:1":"ولما كمل هذا خرج كل إسرائيل الحاضرين إلى مدن يهوذا وكسروا الأنصاب وقطعوا السواري وهدموا المرتفعات والمذابح من كل يهوذا وبنيامين ومن أفرايم ومنسى حتى أفنوها ثم رجع كل إسرائيل كل واحد إلى ملكه إلى مدنهم.","31:2":"وأقام حزقيا فرق الكهنة واللاويين حسب أقسامهم كل واحد حسب خدمته: الكهنة واللاويين للمحرقات وذبائح السلامة للخدمة والحمد والتسبيح في أبواب محلات الرب.","31:3":"وأعطى الملك حصة من ماله للمحرقات محرقات الصباح والمساء والمحرقات للسبوت والأشهر والمواسم كما هو مكتوب في شريعة الرب.","31:4":"وقال للشعب سكان أورشليم أن يعطوا حصة الكهنة واللاويين ليتمسكوا بشريعة الرب.","31:5":"ولما شاع الأمر كثر بنو إسرائيل من أوائل الحنطة والمسطار والزيت والعسل ومن كل غلة الحقل وأتوا بعشر الجميع بكثرة.","31:6":"وبنو إسرائيل ويهوذا الساكنون في مدن يهوذا أتوا هم أيضا بعشر البقر والضأن وعشر الأقداس المقدسة للرب إلههم وجعلوها كومة كومة.","31:7":"في الشهر الثالث ابتدأوا بتأسيس الكوم وفي الشهر السابع أكملوا.","31:8":"وجاء حزقيا والرؤساء ورأوا الكوم فباركوا الرب وشعبه إسرائيل.","31:9":"وسأل حزقيا الكهنة واللاويين عن الكوم","31:10":"فأجاب عزريا الكاهن الرأس لبيت صادوق: [منذ ابتدأ بجلب التقدمة إلى بيت الرب أكلنا وشبعنا وفضل عنا بكثرة لأن الرب بارك شعبه والذي فضل هو هذه الكثرة].","31:11":"وأمر حزقيا بإعداد مخادع في بيت الرب فأعدوا.","31:12":"وأتوا بالتقدمة والعشر والأقداس بأمانة. وكان رئيسا عليهم كوننيا اللاوي وشمعي أخوه الثاني","31:13":"ويحيئيل وعززيا ونحث وعسائيل ويريموث ويوزاباد وإيليئيل ويسمخيا ومحث وبنايا وكلاء تحت يد كوننيا وشمعي أخيه حسب تعيين حزقيا الملك وعزريا رئيس بيت الله.","31:14":"وقوري بن يمنة اللاوي البواب نحو الشرق كان على المتبرع به لله لإعطاء تقدمة الرب وأقداس الأقداس.","31:15":"وتحت يده: عدن وبنيامين ويشوع وشمعيا وأمريا وشكنيا في مدن الكهنة بأمانة ليعطوا لإخوتهم حسب الفرق الكبير كالصغير","31:16":"فضلا عن انتساب ذكورهم من ابن ثلاث سنين فما فوق من كل داخل بيت الرب أمر كل يوم بيومه حسب خدمتهم في حراساتهم حسب أقسامهم","31:17":"وانتساب الكهنة حسب بيوت آبائهم واللاويين من ابن عشرين سنة فما فوق حسب حراساتهم وأقسامهم","31:18":"وانتساب جميع أطفالهم ونسائهم وبنيهم وبناتهم في كل الجماعة لأنهم بأمانتهم تقدسوا تقدسا.","31:19":"ومن بني هارون الكهنة في حقول مراعي مدنهم في كل مدينة فمدينة الرجال المعينة أسماؤهم لإعطاء حصص لكل ذكر من الكهنة ولكل من انتسب من اللاويين.","31:20":"هكذا عمل حزقيا في كل يهوذا وعمل ما هو صالح ومستقيم وحق أمام الرب إلهه.","31:21":"وكل عمل ابتدأ به في خدمة بيت الله وفي الشريعة والوصية ليطلب إلهه إنما عمله بكل قلبه وأفلح.","32:1":"وبعد هذه الأمور وهذه الأمانة أتى سنحاريب ملك أشور ودخل يهوذا ونزل على المدن الحصينة وطمع بإخضاعها لنفسه.","32:2":"ولما رأى حزقيا أن سنحاريب قد أتى ووجهه على محاربة أورشليم","32:3":"تشاور هو ورؤساؤه وجبابرته على طم مياه العيون التي هي خارج المدينة فساعدوه.","32:4":"فتجمع شعب كثير وطموا جميع الينابيع والنهر الجاري في وسط الأرض قائلين: [لماذا يأتي ملوك أشور ويجدون مياها غزيرة؟]","32:5":"وتشدد وبنى كل السور المنهدم وأعلاه إلى الأبراج وسورا آخر خارجا وحصن القلعة مدينة داود وعمل سلاحا بكثرة وأتراسا.","32:6":"وجعل رؤساء قتال على الشعب وجمعهم إليه إلى ساحة باب المدينة وطيب قلوبهم قائلا:","32:7":"[تشددوا وتشجعوا. لا تخافوا ولا ترتاعوا من ملك أشور ومن كل الجمهور الذي معه لأن معنا أكثر مما معه.","32:8":"معه ذراع بشر ومعنا الرب إلهنا ليساعدنا ويحارب حروبنا]. فاستند الشعب على كلام حزقيا ملك يهوذا.","32:9":"بعد هذا أرسل سنحاريب ملك أشور عبيده إلى أورشليم. (وهو على لخيش وكل سلطنته معه) إلى حزقيا ملك يهوذا وإلى كل يهوذا الذين في أورشليم يقولون:","32:10":"[هكذا يقول سنحاريب ملك أشور: على ماذا تتكلون وتقيمون في الحصار في أورشليم؟","32:11":"أليس حزقيا يغويكم ليدفعكم للموت بالجوع والعطش قائلا: الرب إلهنا ينقذنا من يد ملك أشور.","32:12":"أليس حزقيا هو الذي أزال مرتفعاته ومذابحه وقال ليهوذا وأورشليم: أمام مذبح واحد تسجدون وعليه توقدون؟","32:13":"أما تعلمون ما فعلته أنا وآبائي بجميع شعوب الأراضي؟ فهل قدرت آلهة أمم الأراضي أن تنقذ أرضها من يدي.","32:14":"من من جميع آلهة هؤلاء الأمم الذين حرمهم آبائي استطاع أن ينقذ شعبه من يدي حتى يستطيع إلهكم أن ينقذكم من يدي؟","32:15":"والآن لا يخدعنكم حزقيا ولا يغوينكم هكذا ولا تصدقوه لأنه لم يقدر إله أمة أو مملكة أن ينقذ شعبه من يدي ويد آبائي. فكم بالحري إلهكم لا ينقذكم من يدي!].","32:16":"وتكلم عبيده أكثر ضد الرب الإله وضد حزقيا عبده.","32:17":"وكتب رسائل لتعيير الرب إله إسرائيل وللتكلم ضده قائلا: [كما أن آلهة أمم الأراضي لم تنقذ شعوبها من يدي كذلك لا ينقذ إله حزقيا شعبه من يدي].","32:18":"وصرخوا بصوت عظيم باليهودي إلى شعب أورشليم الذين على السور لتخويفهم وترويعهم ليأخذوا المدينة.","32:19":"وتكلموا على إله أورشليم كما على آلهة شعوب الأرض صنعة أيدي الناس.","32:20":"فصلى حزقيا الملك وإشعياء بن آموص النبي لذلك وصرخا إلى السماء","32:21":"فأرسل الرب ملاكا فأباد كل جبار بأس ورئيس وقائد في محلة ملك أشور. فرجع بخزي الوجه إلى أرضه. ولما دخل بيت إلهه قتله هناك بالسيف الذين خرجوا من أحشائه.","32:22":"وخلص الرب حزقيا وسكان أورشليم من سنحاريب ملك أشور ومن يد الجميع وحماهم من كل ناحية.","32:23":"وكان كثيرون يأتون بتقدمات الرب إلى أورشليم وتحف لحزقيا ملك يهوذا واعتبر في أعين جميع الأمم بعد ذلك.","32:24":"في تلك الأيام مرض حزقيا إلى حد الموت وصلى إلى الرب فكلمه وأعطاه علامة.","32:25":"ولكن لم يرد حزقيا حسبما أنعم عليه لأن قلبه ارتفع فكان غضب عليه وعلى يهوذا وأورشليم.","32:26":"ثم تواضع حزقيا بسبب ارتفاع قلبه هو وسكان أورشليم فلم يأت عليهم غضب الرب في أيام حزقيا.","32:27":"وكان لحزقيا غنى وكرامة كثيرة جدا وعمل لنفسه خزائن للفضة والذهب والحجارة الكريمة والأطياب والأتراس وكل آنية ثمينة","32:28":"ومخازن لغلة الحنطة والمسطار والزيت وإسطبلات لكل أنواع البهائم وللقطعان.","32:29":"وعمل لنفسه أبراجا ومواشي غنم وبقر بكثرة لأن الله أعطاه أموالا كثيرة جدا.","32:30":"وحزقيا هذا سد مخرج مياه جيحون الأعلى وأجراها تحت الأرض إلى الجهة الغربية من مدينة داود. وأفلح حزقيا في كل عمله.","32:31":"وهكذا في أمر سفراء رؤساء بابل الذين أرسلوا إليه ليسألوا عن الأعجوبة التي كانت في الأرض تركه الله ليجربه ليعلم كل ما في قلبه.","32:32":"وبقية أمور حزقيا ومراحمه مكتوبة في رؤيا إشعياء بن آموص النبي في سفر ملوك يهوذا وإسرائيل.","32:33":"ثم اضطجع حزقيا مع آبائه فدفنوه في عقبة قبور بني داود وعمل له إكراما عند موته كل يهوذا وسكان أورشليم. وملك منسى ابنه عوضا عنه.","33:1":"كان منسى ابن اثنتي عشرة سنة حين ملك وملك خمسا وخمسين سنة في أورشليم.","33:2":"وعمل الشر في عيني الرب حسب رجاسات الأمم الذين طردهم الرب من أمام بني إسرائيل.","33:3":"وعاد فبنى المرتفعات التي هدمها حزقيا أبوه وأقام مذابح للبعليم وعمل سواري وسجد لكل جند السماء وعبدها.","33:4":"وبنى مذابح في بيت الرب الذي قال عنه الرب [في أورشليم يكون اسمي إلى الأبد].","33:5":"وبنى مذابح لكل جند السماء في داري بيت الرب.","33:6":"وعبر بنيه في النار في وادي ابن هنوم وعاف وتفاءل وسحر واستخدم جانا وتابعة وأكثر عمل الشر في عيني الرب لإغاظته.","33:7":"ووضع تمثال الشكل الذي عمله في بيت الله الذي قال الله عنه لداود ولسليمان ابنه [في هذا البيت وفي أورشليم التي اخترت من جميع أسباط إسرائيل أضع اسمي إلى الأبد.","33:8":"ولا أعود أزحزح رجل إسرائيل عن الأرض التي عينت لآبائهم وذلك إذا حفظوا وعملوا كل ما أوصيتهم به كل الشريعة والفرائض والأحكام عن يد موسى].","33:9":"ولكن منسى أضل يهوذا وسكان أورشليم ليعملوا أشر من الأمم الذين طردهم الرب من أمام بني إسرائيل.","33:10":"وكلم الرب منسى وشعبه فلم يصغوا.","33:11":"فجلب الرب عليهم رؤساء جند ملك أشور فأخذوا منسى بخزامة وقيدوه بسلاسل نحاس وذهبوا به إلى بابل.","33:12":"ولما تضايق طلب وجه الرب إلهه وتواضع جدا أمام إله آبائه","33:13":"وصلى إليه فاستجاب له وسمع تضرعه ورده إلى أورشليم إلى مملكته. فعلم منسى أن الرب هو الله.","33:14":"وبعد ذلك بنى سورا خارج مدينة داود غربا إلى جيحون في الوادي وإلى مدخل باب السمك وحوط الأكمة بسور وعلاه جدا. ووضع رؤساء جيوش في جميع المدن الحصينة في يهوذا.","33:15":"وأزال الآلهة الغريبة والصنم من بيت الرب وجميع المذابح التي بناها في جبل بيت الرب وفي أورشليم وطرحها خارج المدينة.","33:16":"ورمم مذبح الرب وذبح عليه ذبائح سلامة وشكر وأمر يهوذا أن يعبدوا الرب إله إسرائيل.","33:17":"إلا أن الشعب كانوا بعد يذبحون على المرتفعات إنما للرب إلههم.","33:18":"وبقية أمور منسى وصلاته إلى إلهه وكلام الرائين الذين كلموه باسم الرب إله إسرائيل هي في أخبار ملوك إسرائيل.","33:19":"وصلاته والاستجابة له وكل خطاياه وخيانته والأماكن التي بنى فيها مرتفعات وأقام سواري وتماثيل قبل تواضعه مكتوبة في أخبار الرائين.","33:20":"ثم اضطجع منسى مع آبائه فدفنوه في بيته وملك آمون ابنه عوضا عنه.","33:21":"كان آمون ابن اثنتين وعشرين سنة حين ملك وملك سنتين في أورشليم.","33:22":"وعمل الشر في عيني الرب كما عمل منسى أبوه وذبح آمون لجميع التماثيل التي عمل منسى أبوه وعبدها.","33:23":"ولم يتواضع أمام الرب كما تواضع منسى أبوه بل ازداد آمون إثما.","33:24":"وفتن عليه عبيده وقتلوه في بيته.","33:25":"وقتل شعب الأرض جميع الفاتنين على الملك آمون وملك شعب الأرض يوشيا ابنه عوضا عنه.","34:1":"كان يوشيا ابن ثماني سنين حين ملك وملك إحدى وثلاثين سنة في أورشليم.","34:2":"وعمل المستقيم في عيني الرب وسار في طرق داود أبيه ولم يحد يمينا ولا شمالا.","34:3":"وفي السنة الثامنة من ملكه إذ كان بعد فتى ابتدأ يطلب إله داود أبيه. وفي السنة الثانية عشرة ابتدأ يطهر يهوذا وأورشليم من المرتفعات والسواري والتماثيل والمسبوكات.","34:4":"وهدموا أمامه مذابح البعليم وتماثيل الشمس التي عليها من فوق قطعها وكسر السواري والتماثيل والمسبوكات ودقها ورشها على قبور الذين ذبحوا لها.","34:5":"وأحرق عظام الكهنة على مذابحهم وطهر يهوذا وأورشليم.","34:6":"وفي مدن منسى وأفرايم وشمعون إلى نفتالي مع خرائبها حولها","34:7":"هدم المذابح والسواري ودق التماثيل ناعما وقطع جميع تماثيل الشمس في كل أرض إسرائيل ثم رجع إلى أورشليم.","34:8":"وفي السنة الثامنة عشرة من ملكه بعد أن طهر الأرض والبيت أرسل شافان بن أصليا ومعسيا رئيس المدينة ويوآخ بن يوآحاز المسجل لأجل ترميم بيت الرب إلهه.","34:9":"فجاءوا إلى حلقيا الكاهن العظيم وأعطوه الفضة المدخلة إلى بيت الله التي جمعها اللاويون حارسو الباب من منسى وأفرايم ومن كل بقية إسرائيل ومن كل يهوذا وبنيامين ثم رجعوا إلى أورشليم.","34:10":"ودفعوها لأيدي عاملي الشغل الموكلين في بيت الرب فدفعوها لعاملي الشغل الذين كانوا يعملون في بيت الرب لأجل إصلاح البيت وترميمه.","34:11":"وأعطوها للنجارين والبنائين ليشتروا حجارة منحوتة وأخشابا للوصل ولأجل تسقيف البيوت التي أخربها ملوك يهوذا.","34:12":"وكان الرجال يعملون العمل بأمانة وعليهم وكلاء يحث وعوبديا اللاويان من بني مراري وزكريا ومشلام من بني القهاتيين لأجل المناظرة ومن اللاويين كل ماهر بآلات الغناء.","34:13":"وكانوا على الحمال ووكلاء على كل عامل شغل في خدمة فخدمة. وكان من اللاويين كتاب وعرفاء وبوابون.","34:14":"وعند إخراجهم الفضة المدخلة إلى بيت الرب وجد حلقيا الكاهن سفر شريعة الرب بيد موسى.","34:15":"فقال حلقيا لشافان الكاتب: [قد وجدت سفر الشريعة في بيت الرب]. وسلم حلقيا السفر إلى شافان.","34:16":"فجاء شافان بالسفر إلى الملك وقال: [كل ما أسلم ليد عبيدك هم يفعلونه.","34:17":"وقد أفرغوا الفضة الموجودة في بيت الرب ودفعوها ليد الوكلاء ويد عاملي الشغل].","34:18":"وأخبر شافان الكاتب الملك: [قد أعطاني حلقيا الكاهن سفرا]. وقرأ فيه شافان أمام الملك.","34:19":"فلما سمع الملك كلام الشريعة مزق ثيابه","34:20":"وأمر الملك حلقيا وأخيقام بن شافان وعبدون بن ميخا وشافان الكاتب وعسايا عبد الملك:","34:21":"[اذهبوا اسألوا الرب من أجلي ومن أجل من بقي من إسرائيل ويهوذا عن كلام السفر الذي وجد لأنه عظيم غضب الرب الذي انسكب علينا من أجل أن آباءنا لم يحفظوا كلام الرب ليعملوا حسب كل ما هو مكتوب في هذا السفر].","34:22":"فذهب حلقيا والذين أمرهم الملك إلى خلدة النبية امرأة شلوم بن توقهة بن حسرة حارس الثياب وهي ساكنة في أورشليم في القسم الثاني وكلموها هكذا.","34:23":"فقالت لهم: [هكذا قال الرب إله إسرائيل: قولوا للرجل الذي أرسلكم إلي.","34:24":"هكذا قال الرب: هئنذا جالب شرا على هذا الموضع وعلى سكانه جميع اللعنات المكتوبة في السفر الذي قرأوه أمام ملك يهوذا.","34:25":"من أجل أنهم تركوني وأوقدوا لآلهة أخرى ليغيظوني بكل أعمال أيديهم. وينسكب غضبي على هذا الموضع ولا ينطفئ.","34:26":"وأما ملك يهوذا الذي أرسلكم لتسألوا من الرب فهكذا تقولون له: هكذا قال الرب إله إسرائيل من جهة الكلام الذي سمعت:","34:27":"من أجل أنه قد رق قلبك وتواضعت أمام الله حين سمعت كلامه على هذا الموضع وعلى سكانه وتواضعت أمامي ومزقت ثيابك وبكيت أمامي يقول الرب قد سمعت أنا أيضا.","34:28":"هئنذا أضمك إلى آبائك فتضم إلى قبرك بسلام وكل الشر الذي أجلبه على هذا الموضع وعلى سكانه لا ترى عيناك]. فردوا على الملك الجواب.","34:29":"وأرسل الملك وجمع كل شيوخ يهوذا وأورشليم","34:30":"وصعد الملك إلى بيت الرب مع كل رجال يهوذا وسكان أورشليم والكهنة واللاويين وكل الشعب من الكبير إلى الصغير وقرأ في آذانهم كل كلام سفر العهد الذي وجد في بيت الرب.","34:31":"ووقف الملك على منبره وقطع عهدا أمام الرب للذهاب وراء الرب ولحفظ وصاياه وشهاداته وفرائضه بكل قلبه وكل نفسه ليعمل كلام العهد المكتوب في هذا السفر.","34:32":"وأوقف كل الموجودين في أورشليم وبنيامين فعمل سكان أورشليم حسب عهد الله إله آبائهم.","34:33":"وأزال يوشيا جميع الرجاسات من كل الأراضي التي لبني إسرائيل وجعل جميع الموجودين في أورشليم يعبدون الرب إلههم. كل أيامه لم يحيدوا من وراء الرب إله آبائهم.","35:1":"وعمل يوشيا في أورشليم فصحا للرب وذبحوا الفصح في الرابع عشر من الشهر الأول.","35:2":"وأقام الكهنة على حراساتهم وشددهم لخدمة بيت الرب.","35:3":"وقال للاويين الذين كانوا يعلمون كل إسرائيل الذين كانوا مقدسين للرب: [اجعلوا تابوت القدس في البيت الذي بناه سليمان بن داود ملك إسرائيل. ليس لكم أن تحملوا على الأكتاف. الآن اخدموا الرب إلهكم وشعبه إسرائيل.","35:4":"وأعدوا بيوت آبائكم حسب فرقكم حسب كتابة داود ملك إسرائيل وحسب كتابة سليمان ابنه.","35:5":"وقفوا في القدس حسب أقسام بيوت آباء إخوتكم بني الشعب وفرق بيوت آباء اللاويين","35:6":"واذبحوا الفصح وتقدسوا وأعدوا إخوتكم ليعملوا حسب كلام الرب عن يد موسى].","35:7":"وأعطى يوشيا لبني الشعب غنما حملانا وجداء جميع ذلك للفصح لكل الموجودين إلى عدد ثلاثين ألفا وثلاثة آلاف من البقر. هذه من مال الملك.","35:8":"ورؤساؤه قدموا تبرعا للشعب والكهنة واللاويين حلقيا وزكريا ويحيئيل رؤساء بيت الله. أعطوا الكهنة للفصح ألفين وست مئة من الغنم ومن البقر ثلاث مئة.","35:9":"وكوننيا وشمعيا ونثنئيل أخواه وحشبيا ويعيئيل ويوزاباد رؤساء اللاويين قدموا للاويين للفصح خمسة آلاف من الغنم ومن البقر خمس مئة.","35:10":"فتهيأت الخدمة وقام الكهنة في مقامهم واللاويون في فرقهم حسب أمر الملك","35:11":"وذبحوا الفصح. ورش الكهنة من أيديهم. وأما اللاويون فكانوا يسلخون.","35:12":"ورفعوا المحرقة ليعطوا حسب أقسام بيوت الآباء لبني الشعب ليقربوا للرب كما هو مكتوب في سفر موسى. وهكذا بالبقر.","35:13":"وشووا الفصح بالنار كالمرسوم. وأما الأقداس فطبخوها في القدور والمراجل والصحاف وبادروا بها إلى جميع بني الشعب.","35:14":"وبعد أعدوا لأنفسهم وللكهنة لأن الكهنة بني هارون كانوا على إصعاد المحرقة والشحم إلى الليل. فأعد اللاويون لأنفسهم وللكهنة بني هارون.","35:15":"والمغنون بنو آساف كانوا في مقامهم حسب أمر داود وآساف وهيمان ويدوثون رائي الملك. والبوابون على باب فباب لم يكن لهم أن يحيدوا عن خدمتهم لأن إخوتهم اللاويين أعدوا لهم.","35:16":"فتهيأ كل خدمة الرب في ذلك اليوم لعمل الفصح وإصعاد المحرقات على مذبح الرب حسب أمر الملك يوشيا.","35:17":"وعمل بنو إسرائيل الموجودون الفصح في ذلك الوقت وعيد الفطير سبعة أيام.","35:18":"ولم يعمل فصح مثله في إسرائيل من أيام صموئيل النبي. وكل ملوك إسرائيل لم يعملوا كالفصح الذي عمله يوشيا والكهنة واللاويون وكل يهوذا وإسرائيل الموجودين وسكان أورشليم.","35:19":"في السنة الثامنة عشرة لملك يوشيا عمل هذا الفصح.","35:20":"بعد كل هذا حين هيأ يوشيا البيت صعد نخو ملك مصر إلى كركميش ليحارب عند الفرات. فخرج يوشيا للقائه.","35:21":"فأرسل إليه رسلا يقول: [ما لي ولك يا ملك يهوذا! لست عليك أنت اليوم ولكن على بيت آخر أحاربه والله أمر بإسراعي. فكف عن الله الذي معي فلا يهلكك].","35:22":"ولم يحول يوشيا وجهه عنه بل تنكر لمقاتلته ولم يسمع لكلام نخو من فم الله بل جاء ليحارب في بقعة مجدو.","35:23":"وأصاب الرماة الملك يوشيا فقال الملك لعبيده: [انقلوني لأني جرحت جدا].","35:24":"فنقله عبيده من المركبة وأركبوه على المركبة الثانية التي له وساروا به إلى أورشليم فمات ودفن في قبور آبائه. وكان كل يهوذا وأورشليم ينوحون على يوشيا.","35:25":"ورثى إرميا يوشيا. وكان جميع المغنين والمغنيات يندبون يوشيا في مراثيهم إلى اليوم وجعلوها فريضة على إسرائيل. وها هي مكتوبة في المراثي.","35:26":"وبقية أمور يوشيا ومراحمه حسبما هو مكتوب في ناموس الرب.","35:27":"وأموره الأولى والأخيرة مكتوبة في سفر ملوك إسرائيل ويهوذا.","36:1":"وأخذ شعب الأرض يهوآحاز بن يوشيا وملكوه عوضا عن أبيه في أورشليم.","36:2":"كان يهوآحاز ابن ثلاث وعشرين سنة حين ملك وملك ثلاثة أشهر في أورشليم","36:3":"وعزله ملك مصر في أورشليم وغرم الأرض بمئة وزنة من الفضة وبوزنة من الذهب.","36:4":"وملك ملك مصر ألياقيم أخاه على يهوذا وأورشليم وغير اسمه إلى يهوياقيم. وأما يهوآحاز أخوه فأخذه نخو وأتى به إلى مصر.","36:5":"كان يهوياقيم ابن خمس وعشرين سنة حين ملك وملك إحدى عشرة سنة في أورشليم وعمل الشر في عيني الرب إلهه.","36:6":"عليه صعد نبوخذنصر ملك بابل وقيده بسلاسل نحاس ليذهب به إلى بابل","36:7":"وأتى نبوخذنصر ببعض آنية بيت الرب إلى بابل وجعلها في هيكله في بابل.","36:8":"وبقية أمور يهوياقيم ورجاساته التي عمل وما وجد فيه مكتوبة في سفر ملوك إسرائيل ويهوذا. وملك يهوياكين ابنه عوضا عنه.","36:9":"كان يهوياكين ابن ثماني سنين حين ملك وملك ثلاثة أشهر وعشرة أيام في أورشليم. وعمل الشر في عيني الرب.","36:10":"وعند رجوع السنة أرسل الملك نبوخذنصر فأتى به إلى بابل مع آنية بيت الرب الثمينة وملك صدقيا أخاه على يهوذا وأورشليم.","36:11":"كان صدقيا ابن إحدى وعشرين سنة حين ملك وملك إحدى عشرة سنة في أورشليم.","36:12":"وعمل الشر في عيني الرب إلهه ولم يتواضع أمام إرميا النبي من فم الرب.","36:13":"وتمرد أيضا على الملك نبوخذنصر الذي حلفه بالله وصلب عنقه وقوى قلبه عن الرجوع إلى الرب إله إسرائيل","36:14":"حتى أن جميع رؤساء الكهنة والشعب أكثروا الخيانة حسب كل رجاسات الأمم ونجسوا بيت الرب الذي قدسه في أورشليم.","36:15":"فأرسل الرب إله آبائهم إليهم عن يد رسله مبكرا ومرسلا لأنه شفق على شعبه وعلى مسكنه","36:16":"فكانوا يهزأون برسل الله ورذلوا كلامه وتهاونوا بأنبيائه حتى ثار غضب الرب على شعبه حتى لم يكن شفاء.","36:17":"فأصعد عليهم ملك الكلدانيين فقتل مختاريهم بالسيف في بيت مقدسهم. ولم يشفق على فتى أو عذراء ولا على شيخ أو أشيب بل دفع الجميع ليده.","36:18":"وجميع آنية بيت الله الكبيرة والصغيرة وخزائن بيت الرب وخزائن الملك ورؤسائه أتى بها جميعا إلى بابل.","36:19":"وأحرقوا بيت الله وهدموا سور أورشليم وأحرقوا جميع قصورها بالنار وأهلكوا جميع آنيتها الثمينة.","36:20":"وسبى الذين بقوا من السيف إلى بابل فكانوا له ولبنيه عبيدا إلى أن ملكت مملكة فارس","36:21":"لإكمال كلام الرب بفم إرميا حتى استوفت الأرض سبوتها لأنها سبتت في كل أيام خرابها لإكمال سبعين سنة.","36:22":"وفي السنة الأولى لكورش ملك فارس لأجل تكميل كلام الرب بفم إرميا نبه الرب روح كورش ملك فارس فأطلق نداء في كل مملكته وكذا بالكتابة قائلا:","36:23":"[هكذا قال كورش ملك فارس إن الرب إله السماء قد أعطاني جميع ممالك الأرض وهو أوصاني أن أبني له بيتا في أورشليم التي في يهوذا. من منكم من جميع شعبه الرب إلهه معه وليصعد]."};
